INSERT INTO public.generations (id, user_id, url, framework, status, test_cases, script, load_time_ms, is_spa, created_at, updated_at, script_selenium, script_cypress, test_cases_selenium, test_cases_cypress, pass_count, fail_count, skip_count, pass_rate, execution_results, page_type, scraped, script_playwright, test_type, project_id, performance_data, result) VALUES (105, 3, 'https://www.saucedemo.com', 'Selenium', 'completed', '[{"id":1,"name":"Happy Path Login","description":"Verifies successful login with valid credentials","steps":["Enter valid username in #user-name","Enter valid password in #password","Click #login-button"],"expected":"Login is successful","type":"positive"},{"id":2,"name":"Invalid Username","description":"Verifies error handling for invalid username","steps":["Enter invalid username in #user-name","Enter valid password in #password","Click #login-button"],"expected":"Error message is displayed","type":"negative"},{"id":3,"name":"Empty Username","description":"Verifies error handling for empty username","steps":["Leave #user-name empty","Enter valid password in #password","Click #login-button"],"expected":"Error message is displayed","type":"negative"},{"id":4,"name":"Empty Password","description":"Verifies error handling for empty password","steps":["Enter valid username in #user-name","Leave #password empty","Click #login-button"],"expected":"Error message is displayed","type":"negative"},{"id":5,"name":"Page Load Performance","description":"Verifies page load time is within acceptable limits","steps":["Load https:\/\/www.saucedemo.com\/"],"expected":"Page load time is less than 4000 ms","type":"performance"}]', 'from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
import time

def setup_driver():
    driver = webdriver.Chrome()
    driver.get(''https://www.saucedemo.com'')
    return driver

def test_happy_path_login(driver):
    username_input = WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''#user-name'')))
    username_input.send_keys(''standard_user'')
    password_input = WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''#password'')))
    password_input.send_keys(''secret_sauce'')
    login_button = WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''#login-button'')))
    login_button.click()

def test_invalid_username(driver):
