    WebDriverWait(driver, 10).until(EC.url_contains(''/''))
    assert ''/'' in driver.current_url, "Navigation failed"


def test_image_load_verification(driver):
    image1 = WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''img[src="https://demoqa.com/assets/Toolsqa-DZdwt2ul.jpg"]'')))
    image2 = WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''img[src="https://demoqa.com/assets/WB-u-E_TRWX.svg"]'')))
    assert image1.is_displayed() and image2.is_displayed(), "Images are not loaded"


def test_page_load_time(driver):
    start_time = time.time()
    driver.get(''https://demoqa.com/'')
    end_time = time.time()
    load_time = end_time - start_time
    assert load_time < 5, "Page load time is more than 5 seconds"


