from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC

def setup_driver():
    from selenium.webdriver.chrome.options import Options
    opts = Options()
    return webdriver.Chrome(options=opts)

def test_1_page_loads_correctly(driver):
    driver.get(''https://books.toscrape.com'')
    assert driver.title != '''', ''Page title is empty''

def test_2_main_navigation_works(driver):
    driver.get(''https://books.toscrape.com'')
    driver.find_element(By.LINK_TEXT, ''Books to Scrape'').click()
    WebDriverWait(driver, 10).until(lambda d: d.current_url != ''https://books.toscrape.com'')
    assert driver.current_url != ''https://books.toscrape.com'', ''Navigation failed''
    driver.find_element(By.LINK_TEXT, ''Books'').click()
    WebDriverWait(driver, 10).until(lambda d: d.current_url != ''https://books.toscrape.com'')
    assert driver.current_url != ''https://books.toscrape.com'', ''Navigation failed''

def test_3_key_buttons_are_clickable(driver):
    driver.get(''https://books.toscrape.com'')
    btn = WebDriverWait(driver, 10).until(EC.element_to_be_clickable((By.CSS_SELECTOR, ''.btn'')))
    assert btn is not None, ''Button not found''
    assert btn.is_displayed(), ''Button not visible''
    assert btn.is_enabled(), ''Button not enabled''

def test_4_page_performance(driver):
    import time
    start = time.time()
    driver.get(''https://books.toscrape.com'')
    elapsed = time.time() - start
    assert elapsed < 5, f''Page too slow: {elapsed:.2f}s''

def test_5_error_message_is_not_visible(driver):
    driver.get(''https://books.toscrape.com'')
    error = WebDriverWait(driver, 10).until(EC.invisibility_of_element_located((By.CSS_SELECTOR, ''#messages'')))
    assert error is not None, ''Error should be invisible''

if __name__ == ''__main__'':
    driver = setup_driver()
    try:
        try:
            test_1_page_loads_correctly(driver)
            print(''Test 1: PASSED'')
        except AssertionError as e:
            print(''Test 1: FAILED'')
        except Exception as e:
            print(''Test 1: FAILED'')

        try:
            test_2_main_navigation_works(driver)
            print(''Test 2: PASSED'')
        except AssertionError as e:
            print(''Test 2: FAILED'')
        except Exception as e:
            print(''Test 2: FAILED'')

        try:
            test_3_key_buttons_are_clickable(driver)
            print(''Test 3: PASSED'')
        except AssertionError as e:
            print(''Test 3: FAILED'')
        except Exception as e:
            print(''Test 3: FAILED'')

        try:
            test_4_page_performance(driver)
            print(''Test 4: PASSED'')
        except AssertionError as e:
            print(''Test 4: FAILED'')
        except Exception as e:
            print(''Test 4: FAILED'')

        try:
            test_5_error_message_is_not_visible(driver)
            print(''Test 5: PASSED'')
        except AssertionError as e:
            print(''Test 5: FAILED'')
        except Exception as e:
            print(''Test 5: FAILED'')
    finally:
        driver.quit()
', 3808, false, '2026-04-12 21:14:40', '2026-04-12 21:14:40', '', '', '[]', '[]', 5, 0, 0, 100, '[{"name":"Page loads correctly","status":"pass","duration":"\u2014","error":null,"reason":null,"reason_pass":"Toutes les assertions validees \u2014 comportement attendu confirme.","reason_skip":null},{"name":"Main navigation works","status":"pass","duration":"\u2014","error":null,"reason":null,"reason_pass":"Navigation reussie \u2014 page cible chargee correctement.","reason_skip":null},{"name":"Key buttons are clickable","status":"pass","duration":"\u2014","error":null,"reason":null,"reason_pass":"Toutes les assertions validees \u2014 comportement attendu confirme.","reason_skip":null},{"name":"Page performance","status":"pass","duration":"\u2014","error":null,"reason":null,"reason_pass":"Toutes les assertions validees \u2014 comportement attendu confirme.","reason_skip":null},{"name":"Error message is not visible","status":"pass","duration":"\u2014","error":null,"reason":null,"reason_pass":"Toutes les assertions validees \u2014 comportement attendu confirme.","reason_skip":null}]', 'general', NULL, NULL, 'smoke', NULL, NULL, NULL);
