from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC

def setup_driver():
  return webdriver.Chrome()

def test_1_happy_path_login(driver):
  driver.get(''https://edx.tek-up.de/login.faces'')
  username_input = WebDriverWait(driver, 30).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''#username'')))
  username_input.send_keys(''testuser@test.com'')
  password_input = WebDriverWait(driver, 30).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''#password'')))
  password_input.send_keys(''Test@1234'')
