  login_button.click()
  error = WebDriverWait(driver, 10).until(EC.visibility_of_element_located((By.CSS_SELECTOR, ''#error'')))
  assert error.is_displayed(), ''Error message should be visible for empty required field''

def test_4_reset_password(driver):
  driver.get(''https://edx.tek-up.de/login.faces'')
  reset_button = WebDriverWait(driver, 30).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''#reset'')))
  reset_button.click()
  assert driver.current_url != ''https://edx.tek-up.de/login.faces'', ''Reset password functionality is triggered''

