    driver.get(''https://rescat.tn/'')
    el = WebDriverWait(driver, 15).until(
        EC.presence_of_element_located((By.CSS_SELECTOR, ''nav, [class*=''navbar''], [class*=''nav-bar''], header nav'')))
    assert el is not None, ''Element not found: nav, [class*=''navbar''], [class*=''nav-bar''], header nav''

