from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
from selenium.webdriver.chrome.options import Options
import time

def setup_driver():
    opts = Options()
    opts.add_argument(''--headless'')
    opts.add_argument(''--no-sandbox'')
    opts.add_argument(''--disable-dev-shm-usage'')
    opts.add_argument(''--window-size=1920,1080'')
    driver = webdriver.Chrome(options=opts)
    driver.set_page_load_timeout(30)
    driver.implicitly_wait(10)
    return driver

def test_1_main_navigation_present(driver):
    driver.get(''https://rescat.tn/'')
    el = WebDriverWait(driver, 15).until(
        EC.presence_of_element_located((By.CSS_SELECTOR, ''nav, [class*=''navbar''], [class*=''nav-bar''], header nav'')))
    assert el is not None, ''Element not found: nav, [class*=''navbar''], [class*=''nav-bar''], header nav''

def test_2_main_content_area_present(driver):
    driver.get(''https://rescat.tn/'')
    el = WebDriverWait(driver, 15).until(
        EC.presence_of_element_located((By.CSS_SELECTOR, ''main, [role=''main''], #main, #content, .main-content'')))
    assert el is not None, ''Element not found: main, [role=''main''], #main, #content, .main-content''

def test_3_page_title__h1__present(driver):
    driver.get(''https://rescat.tn/'')
    el = WebDriverWait(driver, 15).until(
        EC.presence_of_element_located((By.CSS_SELECTOR, ''h1'')))
    assert el is not None, ''Element not found: h1''

