    driver.get(''https://rescat.tn/'')
    try:
        el = WebDriverWait(driver, 10).until(
            EC.presence_of_element_located((By.CSS_SELECTOR, ''form[role=''search''], form[action*=''search''], [class*=''search-form''], [class*=''searchform''], [id*=''search-form''], [id*=''searchform''], [class*=''search-bar''], [class*=''search-box''], input[type=''search''], input[name=''s''], input[placeholder*=''search'' i], input[placeholder*=''recherche'' i], input[placeholder*=''chercher'' i], input[placeholder*=''بحث'' i]'')))
