INSERT INTO public.generations (id, user_id, url, framework, status, test_cases, script, load_time_ms, is_spa, created_at, updated_at, script_selenium, script_cypress, test_cases_selenium, test_cases_cypress, pass_count, fail_count, skip_count, pass_rate, execution_results, page_type, scraped, script_playwright, test_type, project_id, performance_data, result) VALUES (87, 3, 'https://demoqa.com/', 'Selenium', 'completed', '[{"id":1,"name":"test_happy_path","description":"Verifies navigation to demoqa.com","steps":["Navigate to https:\/\/demoqa.com\/","Verify page title is ''demosite''","Verify page load time is less than 3000ms"],"expected":"Page title is ''demosite'' and load time is less than 3000ms","type":"positive"},{"id":2,"name":"test_invalid_inputs","description":"Verifies no invalid input handling","steps":["Navigate to https:\/\/demoqa.com\/","Verify no input fields are present"],"expected":"No input fields are present","type":"positive"},{"id":3,"name":"test_empty_fields","description":"Verifies no empty field handling","steps":["Navigate to https:\/\/demoqa.com\/","Verify no input fields are present"],"expected":"No input fields are present","type":"positive"},{"id":4,"name":"test_boundary_cases","description":"Verifies no boundary case handling","steps":["Navigate to https:\/\/demoqa.com\/","Verify no input fields are present"],"expected":"No input fields are present","type":"positive"},{"id":5,"name":"test_navigation","description":"Verifies navigation link","steps":["Navigate to https:\/\/demoqa.com\/","Click on navigation link with href=''https:\/\/demoqa.com\/''","Verify page title is ''demosite''"],"expected":"Page title is ''demosite''","type":"positive"},{"id":6,"name":"test_images_loading","description":"Verifies images are loaded","steps":["Navigate to https:\/\/demoqa.com\/","Verify image with src=''https:\/\/demoqa.com\/assets\/Toolsqa-DZdwt2ul.jpg'' is loaded","Verify image with src=''https:\/\/demoqa.com\/assets\/WB-u-E_TRWX.svg'' is loaded"],"expected":"Both images are loaded","type":"positive"},{"id":7,"name":"test_performance","description":"Verifies page load time","steps":["Navigate to https:\/\/demoqa.com\/","Verify page load time is less than 3000ms"],"expected":"Page load time is less than 3000ms","type":"positive"}]', 'from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
from selenium.webdriver.common.keys import Keys
import time

def setup_driver():
    driver = webdriver.Chrome()
    return driver

def test_happy_path(driver):
    try:
        driver.get(''https://demoqa.com/'')
        assert driver.title == ''demosite''
        assert driver.execute_script(''return performance.now()'') < 3000
        print(''PASS: test_happy_path'')
    except Exception as e:
        print(''FAIL: test_happy_path'', str(e))

def test_invalid_inputs(driver):
    try:
        driver.get(''https://demoqa.com/'')
        assert len(driver.find_elements(By.TAG_NAME, ''input'')) == 0
        print(''PASS: test_invalid_inputs'')
    except Exception as e:
        print(''FAIL: test_invalid_inputs'', str(e))

def test_empty_fields(driver):
    try:
        driver.get(''https://demoqa.com/'')
        assert len(driver.find_elements(By.TAG_NAME, ''input'')) == 0
        print(''PASS: test_empty_fields'')
    except Exception as e:
        print(''FAIL: test_empty_fields'', str(e))

def test_boundary_cases(driver):
    try:
        driver.get(''https://demoqa.com/'')
        assert len(driver.find_elements(By.TAG_NAME, ''input'')) == 0
        print(''PASS: test_boundary_cases'')
    except Exception as e:
        print(''FAIL: test_boundary_cases'', str(e))

def test_navigation(driver):
    try:
        driver.get(''https://demoqa.com/'')
        nav_link = WebDriverWait(driver, 15).until(EC.visibility_of_element_located((By.XPATH, ''//a[@href="https://demoqa.com/"]'')))
        driver.execute_script(''arguments[0].scrollIntoView(true)'', nav_link)
        nav_link.click()
        assert driver.title == ''demosite''
        print(''PASS: test_navigation'')
    except Exception as e:
        print(''FAIL: test_navigation'', str(e))

def test_images_loading(driver):
    try:
        driver.get(''https://demoqa.com/'')
        image1 = WebDriverWait(driver, 15).until(EC.visibility_of_element_located((By.XPATH, ''//img[@src="https://demoqa.com/assets/Toolsqa-DZdwt2ul.jpg"]'')))
        image2 = WebDriverWait(driver, 15).until(EC.visibility_of_element_located((By.XPATH, ''//img[@src="https://demoqa.com/assets/WB-u-E_TRWX.svg"]'')))
        assert image1.is_enabled() and image2.is_enabled()
        print(''PASS: test_images_loading'')
    except Exception as e:
        print(''FAIL: test_images_loading'', str(e))

def test_performance(driver):
    try:
        driver.get(''https://demoqa.com/'')
        assert driver.execute_script(''return performance.now()'') < 3000
        print(''PASS: test_performance'')
    except Exception as e:
        print(''FAIL: test_performance'', str(e))

def main():
    driver = setup_driver()
    try:
        test_happy_path(driver)
        test_invalid_inputs(driver)
        test_empty_fields(driver)
        test_boundary_cases(driver)
        test_navigation(driver)
        test_images_loading(driver)
        test_performance(driver)
    finally:
        driver.quit()

class TestSuite:
    def __init__(self):
        self.driver = setup_driver()
    def run(self):
        try:
            test_happy_path(self.driver)
            test_invalid_inputs(self.driver)
            test_empty_fields(self.driver)
            test_boundary_cases(self.driver)
            test_navigation(self.driver)
            test_images_loading(self.driver)
            test_performance(self.driver)
        finally:
            self.driver.quit()

if __name__ == ''__main__'':
    main()', 1044, true, '2026-04-08 08:45:37', '2026-04-08 08:45:37', '', '', '[]', '[]', 7, 0, 0, 100, NULL, 'general', NULL, NULL, 'smoke', NULL, NULL, NULL);
INSERT INTO public.generations (id, user_id, url, framework, status, test_cases, script, load_time_ms, is_spa, created_at, updated_at, script_selenium, script_cypress, test_cases_selenium, test_cases_cypress, pass_count, fail_count, skip_count, pass_rate, execution_results, page_type, scraped, script_playwright, test_type, project_id, performance_data, result) VALUES (116, 3, 'https://www.saucedemo.com', 'Selenium', 'completed', '[{"id":1,"name":"Happy Path Login","description":"Verifies successful login with valid credentials","steps":["Enter valid username in #user-name","Enter valid password in #password","Click #login-button"],"expected":"Login is successful","type":"positive"},{"id":2,"name":"Invalid Username","description":"Verifies error message for invalid username","steps":["Enter invalid username in #user-name","Enter valid password in #password","Click #login-button"],"expected":"Error message is displayed in .error-message-container","type":"negative"},{"id":3,"name":"Empty Username","description":"Verifies error message for empty username","steps":["Leave #user-name empty","Enter valid password in #password","Click #login-button"],"expected":"Error message is displayed in .input_error","type":"negative"},{"id":4,"name":"Empty Password","description":"Verifies error message for empty password","steps":["Enter valid username in #user-name","Leave #password empty","Click #login-button"],"expected":"Error message is displayed in .input_error","type":"negative"},{"id":5,"name":"Load Time Performance","description":"Verifies page load time is less than 3000 ms","steps":["Load https:\/\/www.saucedemo.com"],"expected":"Page load time is less than 3000 ms","type":"performance"}]', 'from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
import time

def setup_driver():
    return webdriver.Chrome()

def test_happy_path_login(driver):
    driver.get(''https://www.saucedemo.com'')
    username_input = WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''#user-name'')))
    username_input.send_keys(''standard_user'')
    password_input = WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''#password'')))
    password_input.send_keys(''secret_sauce'')
    login_button = WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''#login-button'')))
    login_button.click()
    WebDriverWait(driver, 10).until(EC.url_contains(''/inventory.html''))
    assert ''/inventory.html'' in driver.current_url, ''Navigation failed''

def test_invalid_username(driver):
    driver.get(''https://www.saucedemo.com'')
    username_input = WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''#user-name'')))
    username_input.send_keys(''invalid_user'')
    password_input = WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''#password'')))
    password_input.send_keys(''secret_sauce'')
    login_button = WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''#login-button'')))
    login_button.click()
    error_message = WebDriverWait(driver, 10).until(EC.visibility_of_element_located((By.CSS_SELECTOR, ''.error-message-container'')))
    assert error_message.is_displayed(), ''Error message should be visible''

def test_empty_username(driver):
    driver.get(''https://www.saucedemo.com'')
    password_input = WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''#password'')))
    password_input.send_keys(''secret_sauce'')
    login_button = WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''#login-button'')))
    login_button.click()
    error_message = WebDriverWait(driver, 10).until(EC.visibility_of_element_located((By.CSS_SELECTOR, ''.input_error'')))
    assert error_message.is_displayed(), ''Error message should be visible''

def test_empty_password(driver):
    driver.get(''https://www.saucedemo.com'')
    username_input = WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''#user-name'')))
    username_input.send_keys(''standard_user'')
    login_button = WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''#login-button'')))
    login_button.click()
