displayed","type":"positive","priority":"medium","category":"functional"},{"id":10,"name":"Page Load Performance","description":"Verifies the page load time is within the expected threshold","preconditions":"Browser open, page accessible","steps":["Open the page https:\/\/rescat.tn","Measure the page load time"],"test_data":{"threshold":30000},"expected":"Page load time is less than 30 seconds","type":"positive","priority":"high","category":"performance"}]', 'from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
from selenium.webdriver.common.keys import Keys
import time

def setup_driver():
  from selenium.webdriver.chrome.options import Options
  opts = Options()
  opts.page_load_strategy = ''normal''
  driver = webdriver.Chrome(options=opts)
  driver.set_page_load_timeout(39)
  driver.implicitly_wait(10)
  return driver

def test_1_page_load_and_title_check(driver):
  driver.get(''https://rescat.tn'')
  WebDriverWait(driver, 39).until(EC.presence_of_element_located((By.TAG_NAME, ''body'')))
  assert driver.title != '''', ''Page title is empty''
  assert ''accueil'' in driver.title.lower(), f''Unexpected title: {driver.title}''

def test_2_navigation_test_faq(driver):
  driver.get(''https://rescat.tn'')
  original_url = driver.current_url
  links = driver.find_elements(By.CSS_SELECTOR, ''a[href]'')
  target = next((l for l in links if ''faq'' in (l.get_attribute(''href'') or '''') and l.get_attribute(''href'') != original_url), None)
  assert target is not None, ''Target link not found''
  target.click()
  WebDriverWait(driver, 39).until(lambda d: d.current_url != original_url)
  assert driver.current_url != original_url, ''Navigation failed''

def test_3_navigation_test_plan_du_site(driver):
  driver.get(''https://rescat.tn'')
  original_url = driver.current_url
  links = driver.find_elements(By.CSS_SELECTOR, ''a[href]'')
  target = next((l for l in links if ''plan-du-site'' in (l.get_attribute(''href'') or '''') and l.get_attribute(''href'') != original_url), None)
  assert target is not None, ''Target link not found''
  target.click()
  WebDriverWait(driver, 39).until(lambda d: d.current_url != original_url)
  assert driver.current_url != original_url, ''Navigation failed''

def test_4_main_buttons_visibility(driver):
  driver.get(''https://rescat.tn'')
  el = WebDriverWait(driver, 39).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''.elementor-button'')))
  assert el.is_displayed(), ''Connexion button not visible''
  el = WebDriverWait(driver, 39).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''.elementskit-menu-close'')))
  assert el.is_displayed(), ''X button not visible''
  el = WebDriverWait(driver, 39).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''.hfe-nav-menu__toggle'')))
  assert el.is_displayed(), ''Menu button not visible''

def test_5_form_detection(driver):
  driver.get(''https://rescat.tn'')
  el = WebDriverWait(driver, 39).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''.hfe-search-button-wrapper'')))
  assert el.is_displayed(), ''Form not detected''

def test_6_form_submission(driver):
  driver.get(''https://rescat.tn'')
  search_box = WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''[name="s"]'')))
  search_box.clear()
  search_box.send_keys(''test'')
  search_box.send_keys(Keys.RETURN)
  WebDriverWait(driver, 15).until(lambda d: d.current_url != driver.current_url)
  assert driver.current_url != driver.current_url, ''Form submission failed''

def test_7_images_visibility(driver):
  driver.get(''https://rescat.tn'')
  img = WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''img'')))
  loaded = driver.execute_script(''return arguments[0].complete && arguments[0].naturalWidth > 0'', img)
  assert loaded, ''Image not loaded''
  img = WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''img[alt="logo-pirc"]'')))
  loaded = driver.execute_script(''return arguments[0].complete && arguments[0].naturalWidth > 0'', img)
  assert loaded, ''Image not loaded''

def test_8_search_with_valid_keyword(driver):
  driver.get(''https://rescat.tn'')
  original_url = driver.current_url
  search_box = WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''[name="s"]'')))
  search_box.clear()
  search_box.send_keys(''test'')
  search_box.send_keys(Keys.RETURN)
  WebDriverWait(driver, 15).until(lambda d: d.current_url != original_url)
  assert driver.current_url != original_url, ''Search did not navigate''

def test_9_search_with_empty_input(driver):
  driver.get(''https://rescat.tn'')
  original_url = driver.current_url
  search_box = WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''[name="s"]'')))
  search_box.clear()
  search_box.send_keys(Keys.RETURN)
  time.sleep(2)
  placeholder = search_box.get_attribute(''placeholder'')
  assert driver.current_url == original_url or placeholder != '''', ''Unexpected behavior on empty search''

def test_10_page_load_performance(driver):
  start = time.time()
  driver.get(''https://rescat.tn'')
  WebDriverWait(driver, 39).until(EC.presence_of_element_located((By.TAG_NAME, ''body'')))
  elapsed = time.time() - start
  assert elapsed < 30, f''Page too slow: {elapsed:.2f}s''

