INSERT INTO public.generations (id, user_id, url, framework, status, test_cases, script, load_time_ms, is_spa, created_at, updated_at, script_selenium, script_cypress, test_cases_selenium, test_cases_cypress, pass_count, fail_count, skip_count, pass_rate, execution_results, page_type, scraped, script_playwright, test_type, project_id, performance_data, result) VALUES (93, 3, 'https://demoqa.com/', 'Selenium', 'completed', '[{"id":1,"name":"test_happy_path","description":"Verifies navigation to demoqa.com","steps":["Navigate to https:\/\/demoqa.com\/","Verify page title is ''demosite''","Verify nav link is present and clickable"],"expected":"Page title is ''demosite'' and nav link is clickable","type":"positive"},{"id":2,"name":"test_invalid_inputs","description":"Verifies no invalid input handling","steps":["Navigate to https:\/\/demoqa.com\/","Verify no input fields are present"],"expected":"No input fields are present","type":"positive"},{"id":3,"name":"test_empty_fields","description":"Verifies no empty field handling","steps":["Navigate to https:\/\/demoqa.com\/","Verify no input fields are present"],"expected":"No input fields are present","type":"positive"},{"id":4,"name":"test_boundary_cases","description":"Verifies no boundary case handling","steps":["Navigate to https:\/\/demoqa.com\/","Verify no input fields are present"],"expected":"No input fields are present","type":"positive"},{"id":5,"name":"test_navigation","description":"Verifies navigation link","steps":["Navigate to https:\/\/demoqa.com\/","Click on nav link","Verify page redirects to https:\/\/demoqa.com\/"],"expected":"Page redirects to https:\/\/demoqa.com\/","type":"positive"},{"id":6,"name":"test_images_loading","description":"Verifies images are loaded","steps":["Navigate to https:\/\/demoqa.com\/","Verify image with src ''https:\/\/demoqa.com\/assets\/Toolsqa-DZdwt2ul.jpg'' is loaded","Verify image with src ''https:\/\/demoqa.com\/assets\/WB-u-E_TRWX.svg'' is loaded"],"expected":"Images are loaded","type":"positive"},{"id":7,"name":"test_performance","description":"Verifies page load time","steps":["Navigate to https:\/\/demoqa.com\/","Verify page load time is less than 3000ms"],"expected":"Page load time is less than 3000ms","type":"positive"}]', 'from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
from selenium.webdriver.common.keys import Keys
import time

def setup_driver():
    driver = webdriver.Chrome()
    return driver

def test_happy_path(driver):
    try:
        driver.get(''https://demoqa.com/'')
        assert driver.title == ''demosite''
        nav_link = WebDriverWait(driver, 15).until(EC.visibility_of_element_located((By.XPATH, ''//nav/a'')))
        print(''PASS'')
    except Exception as e:
        print(''FAIL'')

def test_invalid_inputs(driver):
    try:
        driver.get(''https://demoqa.com/'')
        assert len(driver.find_elements(By.TAG_NAME, ''input'')) == 0
        print(''PASS'')
    except Exception as e:
        print(''FAIL'')

def test_empty_fields(driver):
    try:
        driver.get(''https://demoqa.com/'')
        assert len(driver.find_elements(By.TAG_NAME, ''input'')) == 0
        print(''PASS'')
    except Exception as e:
        print(''FAIL'')

def test_boundary_cases(driver):
    try:
        driver.get(''https://demoqa.com/'')
        assert len(driver.find_elements(By.TAG_NAME, ''input'')) == 0
        print(''PASS'')
    except Exception as e:
        print(''FAIL'')

def test_navigation(driver):
    try:
        driver.get(''https://demoqa.com/'')
        nav_link = WebDriverWait(driver, 15).until(EC.visibility_of_element_located((By.XPATH, ''//nav/a'')))
        driver.execute_script(''arguments[0].scrollIntoView(true)'', nav_link)
        nav_link.click()
        old_url = driver.current_url
        WebDriverWait(driver, 15).until(EC.url_changes(old_url))
        print(''PASS'')
    except Exception as e:
        print(''FAIL'')

def test_images_loading(driver):
    try:
        driver.get(''https://demoqa.com/'')
        image1 = WebDriverWait(driver, 15).until(EC.visibility_of_element_located((By.XPATH, ''//img[@src="https://demoqa.com/assets/Toolsqa-DZdwt2ul.jpg"]'')))
        image2 = WebDriverWait(driver, 15).until(EC.visibility_of_element_located((By.XPATH, ''//img[@src="https://demoqa.com/assets/WB-u-E_TRWX.svg"]'')))
        print(''PASS'')
    except Exception as e:
        print(''FAIL'')

def test_performance(driver):
    try:
        start_time = time.time()
        driver.get(''https://demoqa.com/'')
        end_time = time.time()
        load_time = end_time - start_time
        assert load_time < 3
        print(''PASS'')
    except Exception as e:
        print(''FAIL'')

def main():
    driver = setup_driver()
    try:
        test_happy_path(driver)
        test_invalid_inputs(driver)
        test_empty_fields(driver)
        test_boundary_cases(driver)
        test_navigation(driver)
        test_images_loading(driver)
        test_performance(driver)
    finally:
        driver.quit()

class TestSuite:
    def __init__(self):
        self.driver = setup_driver()
    def run(self):
        try:
            test_happy_path(self.driver)
            test_invalid_inputs(self.driver)
            test_empty_fields(self.driver)
            test_boundary_cases(self.driver)
            test_navigation(self.driver)
            test_images_loading(self.driver)
            test_performance(self.driver)
        finally:
            self.driver.quit()

if __name__ == ''__main__'':
    main()', 1463, true, '2026-04-08 09:02:37', '2026-04-08 09:02:37', '', '', '[]', '[]', 7, 0, 0, 100, NULL, 'general', NULL, NULL, 'smoke', NULL, NULL, NULL);
INSERT INTO public.generations (id, user_id, url, framework, status, test_cases, script, load_time_ms, is_spa, created_at, updated_at, script_selenium, script_cypress, test_cases_selenium, test_cases_cypress, pass_count, fail_count, skip_count, pass_rate, execution_results, page_type, scraped, script_playwright, test_type, project_id, performance_data, result) VALUES (160, 3, 'https://the-internet.herokuapp.com/login', 'Selenium', 'completed', '[{"id":1,"name":"Valid Login","description":"Verifies successful login with valid credentials","steps":["Enter valid username in #username","Enter valid password in #password","Click .radius"],"expected":"Login successful","type":"positive"},{"id":2,"name":"Invalid Username","description":"Verifies error message for invalid username","steps":["Enter invalid username in #username","Enter valid password in #password","Click .radius"],"expected":"Error message displayed in #flash-messages","type":"negative"},{"id":3,"name":"Invalid Password","description":"Verifies error message for invalid password","steps":["Enter valid username in #username","Enter invalid password in #password","Click .radius"],"expected":"Error message displayed in #flash-messages","type":"negative"},{"id":4,"name":"Empty Fields","description":"Verifies error message for empty fields","steps":["Click .radius with empty #username and #password"],"expected":"Error message displayed in #flash-messages","type":"negative"},{"id":5,"name":"Page Load Time","description":"Verifies page load time is less than 3000 ms","steps":["Load page https:\/\/the-internet.herokuapp.com\/login"],"expected":"Page load time is less than 3000 ms","type":"performance"}]', 'from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC

def setup_driver():
    return webdriver.Chrome()

def test_valid_login(driver):
    driver.get(''https://the-internet.herokuapp.com/login'')
    username_input = WebDriverWait(driver, 30).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''#username'')))
    username_input.send_keys(''admin'')
    password_input = WebDriverWait(driver, 30).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''#password'')))
    password_input.send_keys(''admin'')
    login_button = WebDriverWait(driver, 30).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''.radius'')))
    login_button.click()
    WebDriverWait(driver, 10).until(EC.url_contains(''/secure''))
    assert ''/secure'' in driver.current_url, ''Login failed''

def test_invalid_username(driver):
    driver.get(''https://the-internet.herokuapp.com/login'')
    username_input = WebDriverWait(driver, 30).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''#username'')))
    username_input.send_keys(''invalid'')
    password_input = WebDriverWait(driver, 30).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''#password'')))
    password_input.send_keys(''admin'')
    login_button = WebDriverWait(driver, 30).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''.radius'')))
    login_button.click()
    error = WebDriverWait(driver, 10).until(EC.visibility_of_element_located((By.CSS_SELECTOR, ''.flash.error'')))
    assert error.is_displayed(), ''Error message should be visible''

def test_invalid_password(driver):
    driver.get(''https://the-internet.herokuapp.com/login'')
    username_input = WebDriverWait(driver, 30).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''#username'')))
    username_input.send_keys(''admin'')
    password_input = WebDriverWait(driver, 30).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''#password'')))
    password_input.send_keys(''invalid'')
