from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
from selenium.webdriver.common.keys import Keys
import time

def setup_driver():
  from selenium.webdriver.chrome.options import Options
  opts = Options()
  opts.page_load_strategy = ''normal''
  driver = webdriver.Chrome(options=opts)
  driver.set_page_load_timeout(30)
  driver.implicitly_wait(10)
  return driver

def test_1_page_load_and_title_check(driver):
  driver.get(''https://rescat.tn/'')
  WebDriverWait(driver, 30).until(EC.presence_of_element_located((By.TAG_NAME, ''body'')))
  assert driver.title != '''', ''Page title is empty''
  assert ''accueil'' in driver.title.lower(), f''Unexpected title: {driver.title}''

def test_2_navigation_to_faq_page(driver):
  driver.get(''https://rescat.tn/'')
  original_url = driver.current_url
  links = driver.find_elements(By.CSS_SELECTOR, ''a[href*="faq"]'')
  target = next((l for l in links if l.get_attribute(''href'') != original_url), None)
  assert target is not None, ''Target link not found''
  target.click()
  WebDriverWait(driver, 30).until(lambda d: d.current_url != original_url)
  assert driver.current_url != original_url, ''Navigation failed''

def test_3_navigation_to_plan_du_site_page(driver):
  driver.get(''https://rescat.tn/'')
  original_url = driver.current_url
  links = driver.find_elements(By.CSS_SELECTOR, ''a[href*="plan-du-site"]'')
  target = next((l for l in links if l.get_attribute(''href'') != original_url), None)
  assert target is not None, ''Target link not found''
  target.click()
  WebDriverWait(driver, 30).until(lambda d: d.current_url != original_url)
  assert driver.current_url != original_url, ''Navigation failed''

def test_4_navigation_to_glossaire_page(driver):
  driver.get(''https://rescat.tn/'')
  original_url = driver.current_url
  links = driver.find_elements(By.CSS_SELECTOR, ''a[href*="glossaire"]'')
  target = next((l for l in links if l.get_attribute(''href'') != original_url), None)
  assert target is not None, ''Target link not found''
  target.click()
  WebDriverWait(driver, 30).until(lambda d: d.current_url != original_url)
  assert driver.current_url != original_url, ''Navigation failed''

def test_5_main_buttons_visibility(driver):
  driver.get(''https://rescat.tn/'')
  el = WebDriverWait(driver, 30).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''.elementor-button'')))
  assert el.is_displayed(), ''Element not visible''
  el = WebDriverWait(driver, 30).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''.elementskit-menu-close'')))
  assert el.is_displayed(), ''Element not visible''
  el = WebDriverWait(driver, 30).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''.hfe-nav-menu__toggle'')))
  assert el.is_displayed(), ''Element not visible''

def test_6_form_detection(driver):
  driver.get(''https://rescat.tn/'')
  el = WebDriverWait(driver, 30).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''.hfe-search-button-wrapper'')))
  assert el.is_displayed(), ''Element not visible''

def test_7_form_submission(driver):
  driver.get(''https://rescat.tn/'')
  search_box = WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''[name="s"]'')))
  search_box.clear()
  search_box.send_keys(''test'')
  search_box.send_keys(Keys.RETURN)
  WebDriverWait(driver, 15).until(lambda d: d.current_url != driver.current_url)
  assert driver.current_url != driver.current_url, ''Navigation failed''

def test_8_images_visibility(driver):
  driver.get(''https://rescat.tn/'')
  img = WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''img'')))
  loaded = driver.execute_script(''return arguments[0].complete && arguments[0].naturalWidth > 0'', img)
  assert loaded, ''Image not loaded''
  img = WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''img[alt="logo-pirc"]'')))
  loaded = driver.execute_script(''return arguments[0].complete && arguments[0].naturalWidth > 0'', img)
  assert loaded, ''Image not loaded''

def test_9_search_with_valid_keyword(driver):
  driver.get(''https://rescat.tn/'')
