INSERT INTO public.generations (id, user_id, url, framework, status, test_cases, script, load_time_ms, is_spa, created_at, updated_at, script_selenium, script_cypress, test_cases_selenium, test_cases_cypress, pass_count, fail_count, skip_count, pass_rate, execution_results, page_type, scraped, script_playwright, test_type, project_id, performance_data, result) VALUES (182, 4, 'https://books.toscrape.com', 'Selenium', 'completed', '[{"id":1,"name":"Page loads correctly","description":"Verify page title is visible","steps":["driver.title == ''All products | Books to Scrape - Sandbox''"],"expected":"Page title is visible","type":"positive"},{"id":2,"name":"Main navigation works","description":"Verify navigation links are clickable","steps":["driver.find_element(By.LINK_TEXT, ''Books to Scrape'').click()","driver.find_element(By.LINK_TEXT, ''Books'').click()"],"expected":"Navigation links are clickable","type":"positive"},{"id":3,"name":"Key buttons are clickable","description":"Verify buttons are clickable","steps":["driver.find_element(By.CSS_SELECTOR, ''.btn'').click()"],"expected":"Buttons are clickable","type":"positive"},{"id":4,"name":"Page performance","description":"Verify page loads within 3000ms","steps":["driver.execute_script(''return performance.now();'') < 3000"],"expected":"Page loads within 3000ms","type":"positive"},{"id":5,"name":"Error message is not visible","description":"Verify error message is not visible","steps":["driver.find_element(By.CSS_SELECTOR, ''#messages'').text == ''''"],"expected":"Error message is not visible","type":"positive"}]', '
from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC

def setup_driver():
    from selenium.webdriver.chrome.options import Options
    opts = Options()
    return webdriver.Chrome(options=opts)

def test_1_page_loads_correctly(driver):
    driver.get(''https://books.toscrape.com'')
    assert driver.title != '''', ''Page title is empty''

def test_2_main_navigation_works(driver):
    driver.get(''https://books.toscrape.com'')
    driver.find_element(By.LINK_TEXT, ''Books to Scrape'').click()
    WebDriverWait(driver, 10).until(lambda d: d.current_url != ''https://books.toscrape.com'')
    assert driver.current_url != ''https://books.toscrape.com'', ''Navigation failed''
    driver.find_element(By.LINK_TEXT, ''Books'').click()
    WebDriverWait(driver, 10).until(lambda d: d.current_url != ''https://books.toscrape.com'')
    assert driver.current_url != ''https://books.toscrape.com'', ''Navigation failed''

def test_3_key_buttons_are_clickable(driver):
    driver.get(''https://books.toscrape.com'')
    btn = WebDriverWait(driver, 10).until(EC.element_to_be_clickable((By.CSS_SELECTOR, ''.btn'')))
    assert btn is not None, ''Button not found''
    assert btn.is_displayed(), ''Button not visible''
    assert btn.is_enabled(), ''Button not enabled''

def test_4_page_performance(driver):
    import time
    start = time.time()
    driver.get(''https://books.toscrape.com'')
    elapsed = time.time() - start
    assert elapsed < 5, f''Page too slow: {elapsed:.2f}s''

def test_5_error_message_is_not_visible(driver):
    driver.get(''https://books.toscrape.com'')
    error = WebDriverWait(driver, 10).until(EC.invisibility_of_element_located((By.CSS_SELECTOR, ''#messages'')))
    assert error is not None, ''Error should not be visible''

if __name__ == ''__main__'':
    driver = setup_driver()
    try:
        try:
            test_1_page_loads_correctly(driver)
            print(''Test 1: PASSED'')
        except AssertionError as e:
            print(''Test 1: FAILED'')
        except Exception as e:
            print(''Test 1: FAILED'')

        try:
            test_2_main_navigation_works(driver)
            print(''Test 2: PASSED'')
        except AssertionError as e:
            print(''Test 2: FAILED'')
        except Exception as e:
            print(''Test 2: FAILED'')

        try:
            test_3_key_buttons_are_clickable(driver)
            print(''Test 3: PASSED'')
        except AssertionError as e:
            print(''Test 3: FAILED'')
        except Exception as e:
            print(''Test 3: FAILED'')

        try:
            test_4_page_performance(driver)
            print(''Test 4: PASSED'')
        except AssertionError as e:
            print(''Test 4: FAILED'')
        except Exception as e:
            print(''Test 4: FAILED'')

        try:
            test_5_error_message_is_not_visible(driver)
            print(''Test 5: PASSED'')
        except AssertionError as e:
            print(''Test 5: FAILED'')
        except Exception as e:
            print(''Test 5: FAILED'')
    finally:
        driver.quit()
', 1343, false, '2026-04-12 20:35:19', '2026-04-12 20:35:19', '', '', '[]', '[]', 5, 0, 0, 100, '[{"name":"Page loads correctly","status":"pass","duration":"\u2014","error":null},{"name":"Main navigation works","status":"pass","duration":"\u2014","error":null},{"name":"Key buttons are clickable","status":"pass","duration":"\u2014","error":null},{"name":"Page performance","status":"pass","duration":"\u2014","error":null},{"name":"Error message is not visible","status":"pass","duration":"\u2014","error":null}]', 'general', NULL, NULL, 'smoke', NULL, NULL, NULL);
INSERT INTO public.generations (id, user_id, url, framework, status, test_cases, script, load_time_ms, is_spa, created_at, updated_at, script_selenium, script_cypress, test_cases_selenium, test_cases_cypress, pass_count, fail_count, skip_count, pass_rate, execution_results, page_type, scraped, script_playwright, test_type, project_id, performance_data, result) VALUES (234, 4, 'https://rescat.tn/', 'Selenium', 'completed', '[{"id":1,"name":"Page Load and Title Check","description":"Verifies the page loads correctly and has the expected title","preconditions":"Browser open, page accessible","steps":["Open the page https:\/\/rescat.tn\/","Get the page title"],"test_data":[],"expected":"Accueil - RESCAT","type":"positive","priority":"high","category":"functional"},{"id":2,"name":"Navigation to FAQ Page","description":"Verifies navigation to the FAQ page","preconditions":"Browser open, page accessible","steps":["Open the page https:\/\/rescat.tn\/","Get the href of the FAQ link","Navigate to the FAQ page using driver.get(href)"],"test_data":[],"expected":"The FAQ page loads correctly","type":"positive","priority":"medium","category":"navigation"},{"id":3,"name":"Navigation to Plan du Site Page","description":"Verifies navigation to the Plan du Site page","preconditions":"Browser open, page accessible","steps":["Open the page https:\/\/rescat.tn\/","Get the href of the Plan du Site link","Navigate to the Plan du Site page using driver.get(href)"],"test_data":[],"expected":"The Plan du Site page loads correctly","type":"positive","priority":"medium","category":"navigation"},{"id":4,"name":"Navigation to Glossaire Page","description":"Verifies navigation to the Glossaire page","preconditions":"Browser open, page accessible","steps":["Open the page https:\/\/rescat.tn\/","Get the href of the Glossaire link","Navigate to the Glossaire page using driver.get(href)"],"test_data":[],"expected":"The Glossaire page loads correctly","type":"positive","priority":"medium","category":"navigation"},{"id":5,"name":"Main Buttons Presence","description":"Verifies the presence of main buttons","preconditions":"Browser open, page accessible","steps":["Open the page https:\/\/rescat.tn\/","Check if the Connexion button is present in the DOM","Check if the X button is present in the DOM","Check if the Menu button is present in the DOM"],"test_data":[],"expected":"All main buttons are present in the DOM","type":"positive","priority":"low","category":"ui"},{"id":6,"name":"Search with Valid Keyword","description":"Verifies search functionality with a valid keyword","preconditions":"Browser open, page accessible","steps":["Open the page https:\/\/rescat.tn\/","Enter a valid keyword in the search input","Submit the search form"],"test_data":{"keyword":"test"},"expected":"The search results page loads correctly","type":"positive","priority":"high","category":"functional"},{"id":7,"name":"Search with Empty Input","description":"Verifies search functionality with an empty input","preconditions":"Browser open, page accessible","steps":["Open the page https:\/\/rescat.tn\/","Submit the search form with an empty input"],"test_data":[],"expected":"The search results page loads correctly or an error message is displayed","type":"positive","priority":"medium","category":"functional"},{"id":8,"name":"Images Visibility","description":"Verifies the visibility of images on the page","preconditions":"Browser open, page accessible","steps":["Open the page https:\/\/rescat.tn\/","Check if the images are visible"],"test_data":[],"expected":"All images are visible","type":"positive","priority":"low","category":"ui"},{"id":9,"name":"Page Performance","description":"Verifies the page load time","preconditions":"Browser open, page accessible","steps":["Open the page https:\/\/rescat.tn\/","Measure the page load time"],"test_data":[],"expected":"The page load time is less than 3000ms","type":"positive","priority":"low","category":"performance"}]', 'from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
from selenium.webdriver.common.keys import Keys
import time

def setup_driver():
  from selenium.webdriver.chrome.options import Options
  opts = Options()
  opts.page_load_strategy = ''normal''
  driver = webdriver.Chrome(options=opts)
  driver.set_page_load_timeout(30)
  driver.implicitly_wait(10)
  return driver

def test_1_page_load(driver):
  driver.get(''https://rescat.tn/'')
  WebDriverWait(driver, 30).until(EC.presence_of_element_located((By.TAG_NAME, ''body'')))
  assert driver.title != '''', ''Page title is empty''
  assert ''accueil'' in driver.title.lower(), f''Unexpected title: {driver.title}''

def test_2_navigation_to_faq(driver):
  driver.get(''https://rescat.tn/'')
  original_url = driver.current_url
  links = driver.find_elements(By.CSS_SELECTOR, ''a[href]'')
  target_href = next((l.get_attribute(''href'') for l in links if ''faq'' in (l.get_attribute(''href'') or '''')), None)
  assert target_href is not None, ''Target link not found''
  driver.get(target_href)
  WebDriverWait(driver, 30).until(lambda d: d.title != '''')
  assert driver.current_url != original_url, ''Navigation failed''

def test_3_navigation_to_plan_du_site(driver):
  driver.get(''https://rescat.tn/'')
  original_url = driver.current_url
  links = driver.find_elements(By.CSS_SELECTOR, ''a[href]'')
  target_href = next((l.get_attribute(''href'') for l in links if ''plan-du-site'' in (l.get_attribute(''href'') or '''')), None)
  assert target_href is not None, ''Target link not found''
  driver.get(target_href)
  WebDriverWait(driver, 30).until(lambda d: d.title != '''')
  assert driver.current_url != original_url, ''Navigation failed''

def test_4_navigation_to_glossaire(driver):
  driver.get(''https://rescat.tn/'')
  original_url = driver.current_url
  links = driver.find_elements(By.CSS_SELECTOR, ''a[href]'')
  target_href = next((l.get_attribute(''href'') for l in links if ''glossaire'' in (l.get_attribute(''href'') or '''')), None)
  assert target_href is not None, ''Target link not found''
  driver.get(target_href)
  WebDriverWait(driver, 30).until(lambda d: d.title != '''')
  assert driver.current_url != original_url, ''Navigation failed''

def test_5_main_buttons_presence(driver):
  driver.get(''https://rescat.tn/'')
  connexion_button = WebDriverWait(driver, 30).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''.elementor-button'')))
  x_button = WebDriverWait(driver, 30).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''.elementskit-menu-close'')))
  menu_button = WebDriverWait(driver, 30).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''.hfe-nav-menu__toggle'')))
  assert connexion_button is not None, ''Connexion button not found''
  assert x_button is not None, ''X button not found''
  assert menu_button is not None, ''Menu button not found''

def test_6_search_with_valid_keyword(driver):
  driver.get(''https://rescat.tn/'')
  original_url = driver.current_url
  search_box = WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''[name="s"]'')))
  search_box.clear()
  search_box.send_keys(''test'')
  search_box.send_keys(Keys.RETURN)
  WebDriverWait(driver, 15).until(lambda d: d.current_url != original_url)
  assert driver.current_url != original_url, ''Search did not navigate''

def test_7_search_with_empty_input(driver):
  driver.get(''https://rescat.tn/'')
  original_url = driver.current_url
  search_box = WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''[name="s"]'')))
  search_box.clear()
  search_box.send_keys(Keys.RETURN)
  time.sleep(2)
  placeholder = search_box.get_attribute(''placeholder'')
  assert driver.current_url == original_url or placeholder != '''', ''Unexpected behavior on empty search''

def test_8_images_visibility(driver):
  driver.get(''https://rescat.tn/'')
  img = WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''img'')))
  loaded = driver.execute_script(''return arguments[0].complete && arguments[0].naturalWidth > 0'', img)
  assert loaded, ''Image not loaded''

def test_9_page_performance(driver):
  start = time.time()
  driver.get(''https://rescat.tn/'')
  WebDriverWait(driver, 30).until(EC.presence_of_element_located((By.TAG_NAME, ''body'')))
  elapsed = time.time() - start
  assert elapsed < 5, f''Page too slow: {elapsed:.2f}s''

tests = [test_1_page_load, test_2_navigation_to_faq, test_3_navigation_to_plan_du_site, test_4_navigation_to_glossaire, test_5_main_buttons_presence, test_6_search_with_valid_keyword, test_7_search_with_empty_input, test_8_images_visibility, test_9_page_performance]
if __name__ == ''__main__'':
  driver = setup_driver()
  passed = failed = 0
  try:
    for i, t in enumerate(tests, 1):
      try:
        t(driver)
        print(f''Test {i}: PASSED'')
        passed += 1
      except (AssertionError, Exception) as e:
        print(f''Test {i}: FAILED — {e}'')
