from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
from selenium.webdriver.common.keys import Keys
import time

def setup_driver():
    from selenium.webdriver.chrome.options import Options
    opts = Options()
    opts.page_load_strategy = ''normal''
    driver = webdriver.Chrome(options=opts)
    driver.set_page_load_timeout(30)
    driver.implicitly_wait(10)
    return driver

def test_1_Page_load_title(driver):
    driver.get(''https://rescat.tn/'')
    WebDriverWait(driver, 30).until(EC.presence_of_element_located((By.TAG_NAME, ''body'')))
    assert driver.title != '''', ''Page title is empty''
    assert ''rescat'' in driver.title.lower(), f''Unexpected title: {driver.title}''

def test_2_Navigation_to_FAQ(driver):
    driver.get(''https://rescat.tn/'')
    original_url = driver.current_url
    links = driver.find_elements(By.CSS_SELECTOR, ''a[href]'')
    target_href = next((l.get_attribute(''href'') for l in links
                        if ''faq'' in (l.get_attribute(''href'') or '''')
                        and l.get_attribute(''href'') != original_url
                        and not (l.get_attribute(''href'') or '''').endswith(''#'')), None)
    assert target_href is not None, ''Target link not found''
    driver.get(target_href)
    WebDriverWait(driver, 30).until(lambda d: d.title != '''')
    assert ''faq'' in driver.current_url, ''Navigation to FAQ failed''

def test_3_Navigation_to_Plan_du_Site(driver):
    driver.get(''https://rescat.tn/'')
    original_url = driver.current_url
    links = driver.find_elements(By.CSS_SELECTOR, ''a[href]'')
    target_href = next((l.get_attribute(''href'') for l in links
                        if ''plan-du-site'' in (l.get_attribute(''href'') or '''')
                        and l.get_attribute(''href'') != original_url
                        and not (l.get_attribute(''href'') or '''').endswith(''#'')), None)
    assert target_href is not None, ''Target link not found''
    driver.get(target_href)
    WebDriverWait(driver, 30).until(lambda d: d.title != '''')
    assert ''plan-du-site'' in driver.current_url, ''Navigation to Plan du Site failed''

def test_4_Main_buttons_presence(driver):
    driver.get(''https://rescat.tn/'')
    WebDriverWait(driver, 30).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''a[href*="faq"]'')))
    WebDriverWait(driver, 30).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''a[href*="plan-du-site"]'')))
    WebDriverWait(driver, 30).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''a[href*="glossaire"]'')))
    WebDriverWait(driver, 30).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''a[href*="#pll_switcher"]'')))
    WebDriverWait(driver, 30).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''a[href*="ar/%d8%a7%d9%84%d8%a7%d8%b3%d8%aa%d9%82%d8%a8%d8%a7%d9%84/"]'')))
    WebDriverWait(driver, 30).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''a[href*="en/home/"]'')))

def test_5_Images_visibility(driver):
    driver.get(''https://rescat.tn/'')
    WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''img[alt="logo-pirc"]'')))
    WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''img'')))

