INSERT INTO public.generations (id, user_id, url, framework, status, test_cases, script, load_time_ms, is_spa, created_at, updated_at, script_selenium, script_cypress, test_cases_selenium, test_cases_cypress, pass_count, fail_count, skip_count, pass_rate, execution_results, page_type, scraped, script_playwright, test_type, project_id, performance_data, result) VALUES (192, 4, 'https://www.saucedemo.com', 'Selenium', 'completed', '[{"id":1,"name":"Valid Credentials \u2192 Login Success","description":"Verify user can login with valid credentials","steps":["input[type=''text''][name=''user-name'']","input[type=''password''][name=''password'']","input[type=''submit''][name=''login-button'']"],"expected":"Login button is enabled","type":"positive"},{"id":2,"name":"Wrong Password \u2192 Error Message Visible","description":"Verify error message is visible when password is incorrect","steps":["input[type=''text''][name=''user-name'']","input[type=''password''][name=''password'']","#password .input_error.form_input"],"expected":"Error message is visible","type":"negative"},{"id":3,"name":"Empty Username \u2192 Error Message Visible","description":"Verify error message is visible when username is empty","steps":["input[type=''text''][name=''user-name'']","#user-name .input_error.form_input"],"expected":"Error message is visible","type":"negative"},{"id":4,"name":"Empty Password \u2192 Error Message Visible","description":"Verify error message is visible when password is empty","steps":["input[type=''password''][name=''password'']","#password .input_error.form_input"],"expected":"Error message is visible","type":"negative"},{"id":5,"name":"Page Performance","description":"Verify page loads within 3 seconds","steps":[],"expected":"Page loads within 3000ms","type":"positive"}]', '
from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
from selenium.webdriver.chrome.options import Options

username = ''standard_user''
password = ''secret_sauce''

def setup_driver():
    opts = Options()
    return webdriver.Chrome(options=opts)

def test_1_Valid_Credentials_Login_Success(driver):
    driver.get(''https://www.saucedemo.com'')
    WebDriverWait(driver, 15).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''#user-name'')))
    driver.find_element(By.CSS_SELECTOR, ''#user-name'').send_keys(username)
    driver.find_element(By.CSS_SELECTOR, ''#password'').send_keys(password)
    driver.find_element(By.CSS_SELECTOR, ''#login-button'').click()
    assert ''/inventory.html'' in driver.current_url, ''Login failed''

def test_2_Wrong_Password_Error_Message_Visible(driver):
    driver.get(''https://www.saucedemo.com'')
    WebDriverWait(driver, 15).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''#user-name'')))
    driver.find_element(By.CSS_SELECTOR, ''#user-name'').send_keys(username)
    driver.find_element(By.CSS_SELECTOR, ''#password'').send_keys(''wrong_password'')
    driver.find_element(By.CSS_SELECTOR, ''#login-button'').click()
    error = WebDriverWait(driver, 10).until(EC.visibility_of_element_located((By.CSS_SELECTOR, ''#password .input_error.form_input'')))
    assert error.is_displayed(), ''Error should be visible''

def test_3_Empty_Username_Error_Message_Visible(driver):
    driver.get(''https://www.saucedemo.com'')
    WebDriverWait(driver, 15).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''#user-name'')))
    driver.find_element(By.CSS_SELECTOR, ''#user-name'').send_keys('''')
    driver.find_element(By.CSS_SELECTOR, ''#password'').send_keys(password)
    driver.find_element(By.CSS_SELECTOR, ''#login-button'').click()
    error = WebDriverWait(driver, 10).until(EC.visibility_of_element_located((By.CSS_SELECTOR, ''#user-name .input_error.form_input'')))
    assert error.is_displayed(), ''Error should be visible''

def test_4_Empty_Password_Error_Message_Visible(driver):
    driver.get(''https://www.saucedemo.com'')
    WebDriverWait(driver, 15).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''#user-name'')))
    driver.find_element(By.CSS_SELECTOR, ''#user-name'').send_keys(username)
    driver.find_element(By.CSS_SELECTOR, ''#password'').send_keys('''')
    driver.find_element(By.CSS_SELECTOR, ''#login-button'').click()
    error = WebDriverWait(driver, 10).until(EC.visibility_of_element_located((By.CSS_SELECTOR, ''#password .input_error.form_input'')))
    assert error.is_displayed(), ''Error should be visible''

def test_5_Page_Performance(driver):
    driver.get(''https://www.saucedemo.com'')
    import time
    start = time.time()
    driver.get(''https://www.saucedemo.com'')
    elapsed = time.time() - start
    assert elapsed < 5, f''Page too slow: {elapsed:.2f}s''

if __name__ == ''__main__'':
    driver = setup_driver()
    try:
        try:
            test_1_Valid_Credentials_Login_Success(driver)
            print(''Test 1: PASSED'')
        except AssertionError as e:
            print(''Test 1: FAILED'')
        except Exception as e:
            print(''Test 1: FAILED'')

        try:
            test_2_Wrong_Password_Error_Message_Visible(driver)
            print(''Test 2: PASSED'')
        except AssertionError as e:
            print(''Test 2: FAILED'')
        except Exception as e:
            print(''Test 2: FAILED'')

        try:
            test_3_Empty_Username_Error_Message_Visible(driver)
            print(''Test 3: PASSED'')
        except AssertionError as e:
            print(''Test 3: FAILED'')
        except Exception as e:
            print(''Test 3: FAILED'')

        try:
            test_4_Empty_Password_Error_Message_Visible(driver)
            print(''Test 4: PASSED'')
        except AssertionError as e:
            print(''Test 4: FAILED'')
        except Exception as e:
            print(''Test 4: FAILED'')

        try:
            test_5_Page_Performance(driver)
            print(''Test 5: PASSED'')
        except AssertionError as e:
            print(''Test 5: FAILED'')
        except Exception as e:
            print(''Test 5: FAILED'')
    finally:
