isible","type":"positive","priority":"low","category":"ui"},{"id":6,"name":"Verify form is submitted successfully","description":"Verify that form is submitted successfully","preconditions":"Browser open, page accessible","steps":["Submit the form","Verify form submission is successful"],"test_data":[],"expected":"Form submission is successful","type":"positive","priority":"high","category":"functional"},{"id":7,"name":"Verify alert message is visible","description":"Verify that alert message is visible","preconditions":"Browser open, page accessible","steps":["Verify alert message is visible"],"test_data":[],"expected":"Alert message is visible","type":"positive","priority":"low","category":"ui"}]', '
from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
from selenium.webdriver.chrome.options import Options
import time

def setup_driver():
    opts = Options()
    return webdriver.Chrome(options=opts)

def test_1(driver):
    driver.get(''https://books.toscrape.com'')
    btn = WebDriverWait(driver, 10).until(EC.element_to_be_clickable((By.CSS_SELECTOR, ''.btn'')))
    btn.click()
    WebDriverWait(driver, 5).until(lambda d: d.current_url != driver.current_url)
    assert driver.current_url != driver.current_url, ''Cart page not loaded after add to cart''

def test_2(driver):
    driver.get(''https://books.toscrape.com'')
    start = time.time()
    driver.get(''https://books.toscrape.com'')
    elapsed = time.time() - start
    assert elapsed < 5, f''Page too slow: {elapsed:.2f}s''

