    driver.get(''https://books.toscrape.com'')
    link = WebDriverWait(driver, 10).until(EC.element_to_be_clickable((By.LINK_TEXT, ''Books to Scrape'')))
    link.click()
    WebDriverWait(driver, 10).until(lambda d: d.current_url != ''https://books.toscrape.com'')
    assert driver.current_url != ''https://books.toscrape.com'', ''Navigation failed''

def test_4(driver):
    driver.get(''https://books.toscrape.com'')
    img = WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''img[alt="A Light in the Attic"]'')))
    loaded = driver.execute_script(''return arguments[0].complete && arguments[0].naturalWidth > 0'', img)
    assert loaded, ''Image not loaded''

def test_5(driver):
    driver.get(''https://books.toscrape.com'')
    error = WebDriverWait(driver, 10).until(EC.visibility_of_element_located((By.CSS_SELECTOR, ''#messages'')))
    assert error.is_displayed(), ''Error not visible''

def test_6(driver):
    driver.get(''https://books.toscrape.com'')
    form = WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''.form-horizontal'')))
    driver.get(''https://books.toscrape.com'')
    assert driver.current_url == ''https://books.toscrape.com'', ''URL did not change''

def test_7(driver):
    driver.get(''https://books.toscrape.com'')
    alert = WebDriverWait(driver, 10).until(EC.visibility_of_element_located((By.CSS_SELECTOR, ''.alert'')))
    assert alert.is_displayed(), ''Alert not visible''

if __name__ == ''__main__'':
