            print(''Test 2: FAILED'')
        except Exception as e:
            print(''Test 2: FAILED'')

        try:
            test_3_add_to_cart_button_click(driver)
            print(''Test 3: PASSED'')
        except AssertionError as e:
            print(''Test 3: FAILED'')
        except Exception as e:
            print(''Test 3: FAILED'')

        try:
            test_4_image_loading(driver)
            print(''Test 4: PASSED'')
        except AssertionError as e:
            print(''Test 4: FAILED'')
        except Exception as e:
            print(''Test 4: FAILED'')

        try:
            test_5_page_performance(driver)
            print(''Test 5: PASSED'')
        except AssertionError as e:
            print(''Test 5: FAILED'')
        except Exception as e:
            print(''Test 5: FAILED'')

        try:
            test_6_error_message_visibility(driver)
            print(''Test 6: PASSED'')
