            print(''Test 6: FAILED'')
        except Exception as e:
            print(''Test 6: FAILED'')

        try:
            test_7_form_submission(driver)
            print(''Test 7: PASSED'')
        except AssertionError as e:
            print(''Test 7: FAILED'')
        except Exception as e:
            print(''Test 7: FAILED'')
    finally:
        driver.quit()
