            print(f''Test 2: FAILED — {e}'')
        try:
            test_3_navigation_test(driver)
            print(''Test 3: PASSED'')
        except (AssertionError, Exception) as e:
            print(f''Test 3: FAILED — {e}'')
        try:
            test_4_image_loading_test(driver)
            print(''Test 4: PASSED'')
        except (AssertionError, Exception) as e:
            print(f''Test 4: FAILED — {e}'')
        try:
            test_5_button_click_test(driver)
            print(''Test 5: PASSED'')
        except (AssertionError, Exception) as e:
            print(f''Test 5: FAILED — {e}'')
        try:
            test_6_form_submission_test(driver)
            print(''Test 6: PASSED'')
        except (AssertionError, Exception) as e:
            print(f''Test 6: FAILED — {e}'')
        try:
            test_7_error_message_test(driver)
            print(''Test 7: PASSED'')
        except (AssertionError, Exception) as e:
            print(f''Test 7: FAILED — {e}'')
    finally:
        driver.quit()
