from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
import time

def setup_driver():
    opts = webdriver.ChromeOptions()
    opts.add_argument(''--no-sandbox'')
    return webdriver.Chrome(options=opts)

def test_1_page_title_page_load_test(driver):
    driver.get(''https://books.toscrape.com'')
    assert driver.title != '''', ''Page title is empty''

def test_2_performance_test(driver):
    start = time.time()
    driver.get(''https://books.toscrape.com'')
    elapsed = time.time() - start
    assert elapsed < 5, f''Page too slow: {elapsed:.2f}s''

def test_3_navigation_test(driver):
    original = driver.current_url
    driver.find_element(By.LINK_TEXT, ''Books to Scrape'').click()
    WebDriverWait(driver, 10).until(lambda d: d.current_url != original)
    assert driver.current_url != original, ''URL did not change after navigation''
    original = driver.current_url
    driver.find_element(By.LINK_TEXT, ''Books'').click()
    WebDriverWait(driver, 10).until(lambda d: d.current_url != original)
    assert driver.current_url != original, ''URL did not change after navigation''

def test_4_image_loading_test(driver):
    img = WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''img[alt="A Light in the Attic"]'')))
    loaded = driver.execute_script(''return arguments[0].complete && arguments[0].naturalWidth > 0'', img)
    assert loaded, ''Image not loaded''
    img = WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''img[alt="Tipping the Velvet"]'')))
    loaded = driver.execute_script(''return arguments[0].complete && arguments[0].naturalWidth > 0'', img)
    assert loaded, ''Image not loaded''

def test_5_button_click_test(driver):
    btn = WebDriverWait(driver, 10).until(EC.element_to_be_clickable((By.CSS_SELECTOR, ''.btn'')))
    btn.click()
    cart = WebDriverWait(driver, 5).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''.basket-mini .btn-group'')))
    assert cart is not None, ''Cart not updated after clicking Add to basket''

def test_6_form_submission_test(driver):
    driver.find_element(By.CSS_SELECTOR, ''.form-horizontal'').submit()
    assert driver.title != '''', ''Page title is empty''

def test_7_error_message_test(driver):
    error = WebDriverWait(driver, 10).until(EC.visibility_of_element_located((By.CSS_SELECTOR, ''#messages'')))
    assert error.is_displayed(), ''Error message not visible''
    error = WebDriverWait(driver, 10).until(EC.visibility_of_element_located((By.CSS_SELECTOR, ''.alert'')))
    assert error.is_displayed(), ''Error message not visible''

if __name__ == ''__main__'':
    driver = setup_driver()
    try:
        test_1_page_title_page_load_test(driver)
        print(''Test 1: PASSED'')
    except (AssertionError, Exception) as e:
        print(f''Test 1: FAILED — {e}'')
    try:
        test_2_performance_test(driver)
        print(''Test 2: PASSED'')
    except (AssertionError, Exception) as e:
        print(f''Test 2: FAILED — {e}'')
    try:
        test_3_navigation_test(driver)
        print(''Test 3: PASSED'')
    except (AssertionError, Exception) as e:
        print(f''Test 3: FAILED — {e}'')
    try:
        test_4_image_loading_test(driver)
        print(''Test 4: PASSED'')
    except (AssertionError, Exception) as e:
        print(f''Test 4: FAILED — {e}'')
    try:
        test_5_button_click_test(driver)
        print(''Test 5: PASSED'')
    except (AssertionError, Exception) as e:
        print(f''Test 5: FAILED — {e}'')
    try:
        test_6_form_submission_test(driver)
        print(''Test 6: PASSED'')
    except (AssertionError, Exception) as e:
        print(f''Test 6: FAILED — {e}'')
    try:
        test_7_error_message_test(driver)
        print(''Test 7: PASSED'')
    except (AssertionError, Exception) as e:
        print(f''Test 7: FAILED — {e}'')
    finally:
        driver.quit()
