from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
from selenium.webdriver.chrome.options import Options

def setup_driver():
    opts = Options()
    return webdriver.Chrome(options=opts)

def test_Page_loads_within_5_seconds(driver):
    driver.get(''https://books.toscrape.com'')
    import time
    start = time.time()
    driver.get(''https://books.toscrape.com'')
    elapsed = time.time() - start
    assert elapsed < 5, f''Page too slow: {elapsed:.2f}s''

def test_Add_to_basket_button_is_clickable(driver):
    driver.get(''https://books.toscrape.com'')
    btn = WebDriverWait(driver, 10).until(EC.element_to_be_clickable((By.CSS_SELECTOR, ''.btn'')))
    btn.click()
    WebDriverWait(driver, 5).until(lambda d: d.current_url != driver.current_url)
    assert driver.current_url != driver.current_url, ''Cart page not loaded after add to cart''

def test_Form_submission_is_successful(driver):
    driver.get(''https://books.toscrape.com'')
    form = WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''.form-horizontal'')))
    form.submit()
    WebDriverWait(driver, 5).until(lambda d: d.current_url != driver.current_url)
    assert driver.current_url != driver.current_url, ''Form submission failed''

def test_Navigation_link_is_clickable(driver):
    driver.get(''https://books.toscrape.com'')
    driver.find_element(By.LINK_TEXT, ''Books to Scrape'').click()
    WebDriverWait(driver, 10).until(lambda d: d.current_url != driver.current_url)
    assert driver.current_url != driver.current_url, ''Navigation failed''

def test_Image_is_loaded(driver):
    driver.get(''https://books.toscrape.com'')
    img = WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''img[alt="A Light in the Attic"]'')))
    loaded = driver.execute_script(''return arguments[0].complete && arguments[0].naturalWidth > 0'', img)
    assert loaded, ''Image not loaded''

def test_Error_message_is_visible(driver):
    driver.get(''https://books.toscrape.com'')
    error = WebDriverWait(driver, 10).until(EC.visibility_of_element_located((By.CSS_SELECTOR, ''#messages'')))
    assert error.is_displayed(), ''Error not visible''

def test_Alert_message_is_visible(driver):
    driver.get(''https://books.toscrape.com'')
    alert = WebDriverWait(driver, 10).until(EC.visibility_of_element_located((By.CSS_SELECTOR, ''.alert'')))
    assert alert.is_displayed(), ''Alert not visible''

if __name__ == ''__main__'':
    driver = setup_driver()
    try:
        try:
            test_Page_loads_within_5_seconds(driver)
            print(''Test 1: PASSED'')
        except (AssertionError, Exception):
            print(''Test 1: FAILED'')
