            print(''Test 2: PASSED'')
        except (AssertionError, Exception):
            print(''Test 2: FAILED'')
        try:
            test_Form_submission_is_successful(driver)
            print(''Test 3: PASSED'')
        except (AssertionError, Exception):
            print(''Test 3: FAILED'')
        try:
            test_Navigation_link_is_clickable(driver)
            print(''Test 4: PASSED'')
        except (AssertionError, Exception):
            print(''Test 4: FAILED'')
        try:
            test_Image_is_loaded(driver)
            print(''Test 5: PASSED'')
        except (AssertionError, Exception):
            print(''Test 5: FAILED'')
        try:
            test_Error_message_is_visible(driver)
            print(''Test 6: PASSED'')
        except (AssertionError, Exception):
            print(''Test 6: FAILED'')
        try:
            test_Alert_message_is_visible(driver)
            print(''Test 7: PASSED'')
        except (AssertionError, Exception):
            print(''Test 7: FAILED'')
    finally:
        driver.quit()
