\": [\"rate<0.20\"]\n  }\n}\n\nexport default function () {\n  let urls = [\n    ''https:\/\/anpe.demopro.tn:10443\/dashboard'',\n    ''https:\/\/anpe.demopro.tn:10443\/statistiques'',\n    ''https:\/\/anpe.demopro.tn:10443\/reception'',\n    ''https:\/\/anpe.demopro.tn:10443\/outbox'',\n    ''https:\/\/anpe.demopro.tn:10443\/traitement_dossier_eie''\n  ];\n\n  group(''ANPE - Tunisia'', function () {\n    for (let url of urls) {\n      let res = http.get(url, { headers: { ''Authorization'': ''Bearer '' } });\n      check(res, { ''status is 200 or 302'': (r) => r.status === 200 || r.status === 302 });\n    }\n  });\n\n  sleep(Math.random() * 2 + 1);\n}","soak":"import http from ''k6\/http'';\nimport { sleep, check, group } from ''k6'';\n\nexport let options = {\n  insecureSkipTLSVerify: true,\n  stages: [\n    { duration: \"1m\", target: 10 },\n    { duration: \"3m\", target: 10 },\n    { duration: \"30s\", target: 0 }\n  ],\n  thresholds: {\n    \"http_req_duration\": [\"p(95)<3000\"],\n    \"http_req_failed\": [\"rate<0.05\"]\n  }\n};\n\nexport default function () {\n  let urls = [\n    ''https:\/\/anpe.demopro.tn:10443\/dashboard'',\n    ''https:\/\/anpe.demopro.tn:10443\/statistiques'',\n    ''https:\/\/anpe.demopro.tn:10443\/reception'',\n    ''https:\/\/anpe.demopro.tn:10443\/outbox'',\n    ''https:\/\/anpe.demopro.tn:10443\/traitement_dossier_eie''\n  ];\n\n  group(''ANPE - Tunisia'', function () {\n    let url = urls[Math.floor(Math.random() * urls.length)];\n    let res = http.get(url, { headers: { ''Authorization'': ''Bearer '' } });\n    check(res, { ''status is 200 or 302'': (r) => r.status === 200 || r.status === 302 });\n  });\n\n  sleep(Math.random() * 2 + 1);\n}"}}');
