fy all navigation links are clickable","preconditions":"Browser open, page accessible","steps":["Click on ''Elements'' link","Click on ''Forms'' link","Click on ''Alerts, Frame & Windows'' link","Click on ''Widgets'' link","Click on ''Interactions'' link","Click on ''Book Store Application'' link"],"test_data":[],"expected":"All links are clickable","type":"positive","priority":"medium","category":"functional"},{"id":6,"name":"Page Load Time Negative","description":"Verify page load time is not less than 5 seconds","preconditions":"Browser open, page accessible","steps":["Open the browser and navigate to https:\/\/demoqa.com"],"test_data":[],"expected":"Page load time is not less than 5 seconds","type":"negative","priority":"high","category":"performance"}]', '
from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
import time

def setup_driver():
    from selenium.webdriver.chrome.options import Options
    opts = Options()
    return webdriver.Chrome(options=opts)

def test_Page_Title_Verification(driver):
    driver.get(''https://demoqa.com'')
    assert driver.title != '''', ''Page title empty''

def test_Navigation_Links_Existence(driver):
    driver.get(''https://demoqa.com'')
    links = [''Elements'', ''Forms'', ''Alerts, Frame & Windows'', ''Widgets'', ''Interactions'', ''Book Store Application'']
    for link in links:
        driver.find_element(By.LINK_TEXT, link).is_displayed()
        assert True, f''Link {link} not found''

def test_Page_Load_Time(driver):
    import time
    start = time.time()
    driver.get(''https://demoqa.com'')
    elapsed = time.time() - start
    assert elapsed < 5, f''Page too slow: {elapsed:.2f}s''

def test_Image_Existence(driver):
    driver.get(''https://demoqa.com'')
    img = WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''img[alt="Selenium Online Training"]'')))
    loaded = driver.execute_script(''return arguments[0].complete && arguments[0].naturalWidth > 0'', img)
    assert loaded, ''Image not loaded''

def test_Navigation_Links_Clickability(driver):
    driver.get(''https://demoqa.com'')
    original = driver.current_url
    links = [''Elements'', ''Forms'', ''Alerts, Frame & Windows'', ''Widgets'', ''Interactions'', ''Book Store Application'']
    for link in links:
        driver.find_element(By.LINK_TEXT, link).click()
        WebDriverWait(driver, 10).until(lambda d: d.current_url != original)
        assert driver.current_url != original, f''Navigation failed for {link}''

def test_Page_Load_Time_Negative(driver):
    import time
    start = time.time()
    driver.get(''https://demoqa.com'')
    elapsed = time.time() - start
    assert elapsed >= 5, f''Page too fast: {elapsed:.2f}s''

if __name__ == ''__main__'':
    driver = setup_driver()
    try:
        try:
            test_Page_Title_Verification(driver)
            print(''Test 1: PASSED'')
        except (AssertionError, Exception):
            print(''Test 1: FAILED'')
        try:
            test_Navigation_Links_Existence(driver)
            print(''Test 2: PASSED'')
        except (AssertionError, Exception):
            print(''Test 2: FAILED'')
        try:
            test_Page_Load_Time(driver)
            print(''Test 3: PASSED'')
        except (AssertionError, Exception):
            print(''Test 3: FAILED'')
        try:
            test_Image_Existence(driver)
            print(''Test 4: PASSED'')
        except (AssertionError, Exception):
            print(''Test 4: FAILED'')
        try:
            test_Navigation_Links_Clickability(driver)
            print(''Test 5: PASSED'')
        except (AssertionError, Exception):
            print(''Test 5: FAILED'')
        try:
            test_Page_Load_Time_Negative(driver)
            print(''Test 6: PASSED'')
        except (AssertionError, Exception):
            print(''Test 6: FAILED'')
    finally:
        driver.quit()
