ge accessible","steps":["Fill in the form with invalid data","Submit the form","Verify the error message is visible"],"test_data":[],"expected":"Error message is visible","type":"positive","priority":"medium","category":"functional"},{"id":6,"name":"Verify page load time","description":"Verifies the page load time is less than 5 seconds","preconditions":"Browser open, page accessible","steps":["Load the page","Measure the page load time"],"test_data":[],"expected":"Page load time is less than 5 seconds","type":"positive","priority":"high","category":"performance"},{"id":7,"name":"Verify button click","description":"Verifies the button with text ''Add to basket'' is clickable","preconditions":"Browser open, page accessible","steps":["Click on the button with text ''Add to basket''","Verify the button click is successful"],"test_data":[],"expected":"Button click is successful","type":"positive","priority":"medium","category":"functional"}]', 'from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
from selenium.webdriver.chrome.options import Options
import time

def setup_driver():
    opts = Options()
    return webdriver.Chrome(options=opts)

def test_1_verify_page_title(driver):
    driver.get(''https://books.toscrape.com'')
    assert driver.title != '''', ''Page title empty''

def test_2_verify_navigation_link(driver):
    driver.get(''https://books.toscrape.com'')
    original = driver.current_url
    driver.find_element(By.LINK_TEXT, ''Books'').click()
    WebDriverWait(driver, 10).until(lambda d: d.current_url != original)
    assert driver.current_url != original, ''Navigation failed''

def test_3_verify_image_loading(driver):
    driver.get(''https://books.toscrape.com'')
    img = WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''img[alt="A Light in the Attic"]'')))
    loaded = driver.execute_script(''return arguments[0].complete && arguments[0].naturalWidth > 0'', img)
    assert loaded, ''Image not loaded''

def test_4_verify_form_submission(driver):
    # No form submission test as no form exists in PAGE ELEMENTS
    pass

def test_5_verify_error_message_visibility(driver):
