from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
from selenium.webdriver.chrome.options import Options

def setup_driver():
    opts = Options()
    return webdriver.Chrome(options=opts)

def test_1_navigation_to_books_category(driver):
    driver.get(''https://books.toscrape.com'')
    original = driver.current_url
    driver.find_element(By.LINK_TEXT, ''Books'').click()
    WebDriverWait(driver, 10).until(lambda d: d.current_url != original)
    assert driver.current_url == ''https://books.toscrape.com/catalogue/category/books_1/index.html'', ''Navigation failed''

def test_2_add_to_basket_button_visibility(driver):
    driver.get(''https://books.toscrape.com'')
    el = WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''.btn'')))
    assert el is not None and el.is_displayed(), ''Element not found or not visible''

def test_3_form_submission(driver):
    driver.get(''https://books.toscrape.com'')
    form = WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''.form-horizontal'')))
    assert form is not None, ''Form not found''

def test_4_error_message_visibility(driver):
    driver.get(''https://books.toscrape.com'')
    error = WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''#messages'')))
    assert error is not None, ''Error not found''

def test_5_page_load_time(driver):
    import time
    start = time.time()
    driver.get(''https://books.toscrape.com'')
    elapsed = time.time() - start
    assert elapsed < 5, f''Page too slow: {elapsed:.2f}s''

def test_6_navigation_to_travel_category(driver):
    driver.get(''https://books.toscrape.com'')
    original = driver.current_url
    driver.find_element(By.LINK_TEXT, ''Travel'').click()
    WebDriverWait(driver, 10).until(lambda d: d.current_url != original)
    assert driver.current_url == ''https://books.toscrape.com/catalogue/category/books/travel_2/index.html'', ''Navigation failed''

def test_7_image_loading(driver):
    driver.get(''https://books.toscrape.com'')
    img = WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''img[alt=\''A Light in the Attic\'']'')))
    loaded = driver.execute_script(''return arguments[0].complete && arguments[0].naturalWidth > 0'', img)
    assert loaded, ''Image not loaded''

if __name__ == ''__main__'':
    driver = setup_driver()
    try:
        try:
            test_1_navigation_to_books_category(driver)
            print(''Test 1: PASSED'')
        except (AssertionError, Exception):
            print(''Test 1: FAILED'')
        try:
            test_2_add_to_basket_button_visibility(driver)
            print(''Test 2: PASSED'')
        except (AssertionError, Exception):
            print(''Test 2: FAILED'')
        try:
            test_3_form_submission(driver)
            print(''Test 3: PASSED'')
        except (AssertionError, Exception):
            print(''Test 3: FAILED'')
        try:
            test_4_error_message_visibility(driver)
            print(''Test 4: PASSED'')
        except (AssertionError, Exception):
            print(''Test 4: FAILED'')
        try:
            test_5_page_load_time(driver)
            print(''Test 5: PASSED'')
        except (AssertionError, Exception):
            print(''Test 5: FAILED'')
        try:
            test_6_navigation_to_travel_category(driver)
            print(''Test 6: PASSED'')
        except (AssertionError, Exception):
            print(''Test 6: FAILED'')
        try:
            test_7_image_loading(driver)
            print(''Test 7: PASSED'')
        except (AssertionError, Exception):
            print(''Test 7: FAILED'')
    finally:
        driver.quit()
