from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
from selenium.webdriver.chrome.options import Options
import time

def setup_driver():
    opts = Options()
    return webdriver.Chrome(options=opts)

def test_1_title(driver):
    driver.get(''https://books.toscrape.com'')
    assert driver.title != '''', ''Page title empty''

def test_2_load_time(driver):
    driver.get(''https://books.toscrape.com'')
    start = time.time()
    driver.get(''https://books.toscrape.com'')
    elapsed = time.time() - start
    assert elapsed < 5, f''Page too slow: {elapsed:.2f}s''

def test_3_navigation(driver):
    original = driver.current_url
    driver.find_element(By.LINK_TEXT, ''Books to Scrape'').click()
    WebDriverWait(driver, 10).until(lambda d: d.current_url != original)
    assert driver.current_url != original, ''Navigation failed''

def test_4_image_loaded(driver):
    img = WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''img[alt="A Light in the Attic"]'')))
    loaded = driver.execute_script(''return arguments[0].complete && arguments[0].naturalWidth > 0'', img)
    assert loaded, ''Image not loaded''

def test_5_form_submission(driver):
    original_url = driver.current_url
    driver.find_element(By.CSS_SELECTOR, ''.form-horizontal'').click()
    WebDriverWait(driver, 5).until(lambda d: d.current_url != original_url)
    assert driver.current_url != original_url, ''Form submission failed''

def test_6_error_message(driver):
    error = WebDriverWait(driver, 10).until(EC.visibility_of_element_located((By.CSS_SELECTOR, ''#messages'')))
    assert error.is_displayed(), ''Error not visible''

def test_7_button_clickable(driver):
    btn = WebDriverWait(driver, 10).until(EC.element_to_be_clickable((By.CSS_SELECTOR, ''.btn'')))
    btn.click()
    WebDriverWait(driver, 5).until(lambda d: d.current_url != driver.current_url)
    assert True, ''Button not clickable''

if __name__ == ''__main__'':
    driver = setup_driver()
    try:
        try:
            test_1_title(driver)
            print(''Test 1: PASSED'')
            test_2_load_time(driver)
            print(''Test 2: PASSED'')
            test_3_navigation(driver)
            print(''Test 3: PASSED'')
            test_4_image_loaded(driver)
            print(''Test 4: PASSED'')
            test_5_form_submission(driver)
            print(''Test 5: PASSED'')
            test_6_error_message(driver)
            print(''Test 6: PASSED'')
            test_7_button_clickable(driver)
            print(''Test 7: PASSED'')
        except (AssertionError, Exception):
            print(''Test failed'')
    finally:
        driver.quit()
