INSERT INTO public.generations (id, user_id, url, framework, status, test_cases, script, load_time_ms, is_spa, created_at, updated_at, script_selenium, script_cypress, test_cases_selenium, test_cases_cypress, pass_count, fail_count, skip_count, pass_rate, execution_results, page_type, scraped, script_playwright, test_type, project_id, performance_data, result) VALUES (218, 4, 'https://books.toscrape.com/', 'Selenium', 'completed', '[{"id":1,"name":"Page loads within 5 seconds","description":"Verify page load time is less than 5 seconds","preconditions":"Browser open, page accessible","steps":["Navigate to https:\/\/books.toscrape.com\/"],"test_data":[],"expected":"Page load time is less than 5 seconds","type":"positive","priority":"high","category":"performance"},{"id":2,"name":"Add to basket button is clickable","description":"Verify Add to basket button is clickable","preconditions":"Browser open, page accessible","steps":["Click on .btn"],"test_data":[],"expected":"Button click is successful","type":"positive","priority":"medium","category":"functional"},{"id":3,"name":"Form submission is successful","description":"Verify form submission is successful","preconditions":"Browser open, page accessible","steps":["Submit .form-horizontal"],"test_data":[],"expected":"Form submission is successful","type":"positive","priority":"medium","category":"functional"},{"id":4,"name":"Navigation link is clickable","description":"Verify navigation link is clickable","preconditions":"Browser open, page accessible","steps":["Click on By.LINK_TEXT: Books to Scrape"],"test_data":[],"expected":"Link click is successful","type":"positive","priority":"low","category":"navigation"},{"id":5,"name":"Image is loaded","description":"Verify image is loaded","preconditions":"Browser open, page accessible","steps":["Verify img[alt=''A Light in the Attic''] is loaded"],"test_data":[],"expected":"Image is loaded","type":"positive","priority":"low","category":"ui"},{"id":6,"name":"Error message is visible","description":"Verify error message is visible","preconditions":"Browser open, page accessible","steps":["Verify #messages is visible"],"test_data":[],"expected":"Error message is visible","type":"positive","priority":"low","category":"ui"},{"id":7,"name":"Alert message is visible","description":"Verify alert message is visible","preconditions":"Browser open, page accessible","steps":["Verify .alert is visible"],"test_data":[],"expected":"Alert message is visible","type":"positive","priority":"low","category":"ui"}]', '
from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
from selenium.webdriver.chrome.options import Options
import time

def setup_driver():
    opts = Options()
    return webdriver.Chrome(options=opts)

def test_Page_loads_within_5_seconds(driver):
    driver.get(''https://books.toscrape.com/'')
    start = time.time()
    driver.get(''https://books.toscrape.com/'')
    elapsed = time.time() - start
    assert elapsed < 5, f''Page too slow: {elapsed:.2f}s''

def test_Add_to_basket_button_is_clickable(driver):
    driver.get(''https://books.toscrape.com/'')
    btn = WebDriverWait(driver, 10).until(EC.element_to_be_clickable((By.CSS_SELECTOR, ''.btn'')))
    btn.click()
    WebDriverWait(driver, 5).until(lambda d: d.current_url != driver.current_url)
    assert driver.current_url != driver.current_url, ''Cart page not loaded''

def test_Form_submission_is_successful(driver):
    driver.get(''https://books.toscrape.com/'')
    form = WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''.form-horizontal'')))
    form.submit()
    WebDriverWait(driver, 5).until(lambda d: d.current_url != driver.current_url)
    assert driver.current_url != driver.current_url, ''Form submission failed''

def test_Navigation_link_is_clickable(driver):
    driver.get(''https://books.toscrape.com/'')
    link = WebDriverWait(driver, 10).until(EC.element_to_be_clickable((By.LINK_TEXT, ''Books to Scrape'')))
    original = driver.current_url
    link.click()
    WebDriverWait(driver, 10).until(lambda d: d.current_url != original)
    assert driver.current_url != original, ''Navigation failed''

def test_Image_is_loaded(driver):
    driver.get(''https://books.toscrape.com/'')
    img = WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''img[alt="A Light in the Attic"]'')))
    loaded = driver.execute_script(''return arguments[0].complete && arguments[0].naturalWidth > 0'', img)
    assert loaded, ''Image not loaded''

def test_Error_message_is_visible(driver):
    driver.get(''https://books.toscrape.com/'')
    error = WebDriverWait(driver, 10).until(EC.visibility_of_element_located((By.CSS_SELECTOR, ''#messages'')))
    assert error.is_displayed(), ''Error not visible''

def test_Alert_message_is_visible(driver):
    driver.get(''https://books.toscrape.com/'')
    alert = WebDriverWait(driver, 10).until(EC.visibility_of_element_located((By.CSS_SELECTOR, ''.alert'')))
    assert alert.is_displayed(), ''Alert not visible''

if __name__ == ''__main__'':
    driver = setup_driver()
    try:
        try:
            test_Page_loads_within_5_seconds(driver)
            print(''Test 1: PASSED'')
            test_Add_to_basket_button_is_clickable(driver)
            print(''Test 2: PASSED'')
            test_Form_submission_is_successful(driver)
            print(''Test 3: PASSED'')
            test_Navigation_link_is_clickable(driver)
            print(''Test 4: PASSED'')
            test_Image_is_loaded(driver)
            print(''Test 5: PASSED'')
            test_Error_message_is_visible(driver)
            print(''Test 6: PASSED'')
            test_Alert_message_is_visible(driver)
            print(''Test 7: PASSED'')
        except (AssertionError, Exception):
            print(''Test failed'')
    finally:
        driver.quit()
