sent","steps":["Fill in form with valid data","Submit the form"],"test_data":{"s":"test","phrase":"test"},"expected":"Form submission is successful","type":"positive","priority":"high","category":"functional"},{"id":6,"name":"Images and sections visibility test","description":"Verifies images and sections are visible on the page","preconditions":"Browser open, page accessible","steps":["Check for images with css_selector ''img''"],"test_data":[],"expected":"Images and sections are visible on the page","type":"positive","priority":"low","category":"ui"},{"id":7,"name":"Search with valid keyword test","description":"Verifies search with valid keyword returns results","preconditions":"Browser open, page accessible, search bar is present","steps":["Enter valid keyword in search bar","Submit the search"],"test_data":{"s":"test"},"expected":"Search results are displayed","type":"positive","priority":"high","category":"functional"},{"id":8,"name":"Search with empty input test","description":"Verifies search with empty input displays placeholder or no change","preconditions":"Browser open, page accessible, search bar is present","steps":["Enter empty input in search bar","Submit the search"],"test_data":{"s":""},"expected":"Placeholder is displayed or no change occurs","type":"positive","priority":"medium","category":"functional"}]', '
from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
from selenium.webdriver.common.keys import Keys

def setup_driver():
    from selenium.webdriver.chrome.options import Options
    from selenium.webdriver.chrome.service import Service
    opts = Options()
    opts.page_load_strategy = ''normal''
    driver = webdriver.Chrome(options=opts)
    driver.set_page_load_timeout(50)
    driver.implicitly_wait(10)
    return driver

def test_1_homepage_load_test(driver):
    driver.get(''https://rescat.tn/'')
    import time
    start = time.time()
    driver.get(''https://rescat.tn/'')
    elapsed = time.time() - start
    assert elapsed < 40, f''Page too slow: {elapsed:.2f}s''

def test_2_navigation_links_test(driver):
    driver.get(''https://rescat.tn/'')
    original = driver.current_url
    try:
        driver.find_element(By.LINK_TEXT, ''RESCAT'').click()
    except Exception:
        driver.find_element(By.CSS_SELECTOR, ''nav a, [class*="nav"] a, header a'').click()
    WebDriverWait(driver, 50).until(lambda d: d.current_url != original)
    assert driver.current_url != original, ''Navigation failed''
    driver.get(''https://rescat.tn/'')
    original = driver.current_url
    try:
        driver.find_element(By.LINK_TEXT, ''FAQ'').click()
    except Exception:
        driver.find_element(By.CSS_SELECTOR, ''nav a, [class*="nav"] a, header a'').click()
    WebDriverWait(driver, 50).until(lambda d: d.current_url != original)
    assert driver.current_url != original, ''Navigation failed''
    driver.get(''https://rescat.tn/'')
    original = driver.current_url
    try:
        driver.find_element(By.LINK_TEXT, ''Plan du Site'').click()
    except Exception:
        driver.find_element(By.CSS_SELECTOR, ''nav a, [class*="nav"] a, header a'').click()
    WebDriverWait(driver, 50).until(lambda d: d.current_url != original)
    assert driver.current_url != original, ''Navigation failed''

def test_3_main_buttons_presence_test(driver):
    driver.get(''https://rescat.tn/'')
    el = WebDriverWait(driver, 50).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''.elementor-button'')))
    assert el is not None and el.is_displayed(), ''Element not found or not visible''
    el = WebDriverWait(driver, 50).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''button'')))
    assert el is not None and el.is_displayed(), ''Element not found or not visible''

def test_4_contact_form_detection_test(driver):
    driver.get(''https://rescat.tn/'')
    el = WebDriverWait(driver, 50).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''.hfe-search-button-wrapper'')))
    assert el is not None and el.is_displayed(), ''Element not found or not visible''

def test_5_form_submission_test(driver):
    driver.get(''https://rescat.tn/'')
    search_box = WebDriverWait(driver, 10).until(
        EC.presence_of_element_located((By.CSS_SELECTOR, ''[name="s"]''))
    )
    search_box.clear()
    search_box.send_keys(''test'')
    search_box.send_keys(Keys.RETURN)
    WebDriverWait(driver, 10).until(lambda d: len(d.find_elements(By.CSS_SELECTOR, ''[class*=result], [class*=item], article'')) > 0
        or d.current_url != driver.current_url)
    results = driver.find_elements(By.CSS_SELECTOR, ''[class*=result], [class*=item], article'')
    assert len(results) > 0 or driver.current_url != driver.current_url, ''No search results appeared''

def test_6_images_and_sections_visibility_test(driver):
    driver.get(''https://rescat.tn/'')
    img = WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''img'')))
    loaded = driver.execute_script(''return arguments[0].complete && arguments[0].naturalWidth > 0'', img)
    assert loaded, ''Image not loaded''

def test_7_search_with_valid_keyword_test(driver):
    driver.get(''https://rescat.tn/'')
    search_box = WebDriverWait(driver, 10).until(
        EC.presence_of_element_located((By.CSS_SELECTOR, ''[name="s"]''))
    )
    search_box.clear()
    search_box.send_keys(''test'')
    search_box.send_keys(Keys.RETURN)
    WebDriverWait(driver, 10).until(lambda d: len(d.find_elements(By.CSS_SELECTOR, ''[class*=result], [class*=item], article'')) > 0
        or d.current_url != driver.current_url)
    results = driver.find_elements(By.CSS_SELECTOR, ''[class*=result], [class*=item], article'')
    assert len(results) > 0 or driver.current_url != driver.current_url, ''No search results appeared''

def test_8_search_with_empty_input_test(driver):
    driver.get(''https://rescat.tn/'')
    search_box = WebDriverWait(driver, 10).until(
        EC.presence_of_element_located((By.CSS_SELECTOR, ''[name="s"]''))
    )
    search_box.clear()
    search_box.send_keys('''')
    search_box.send_keys(Keys.RETURN)
    WebDriverWait(driver, 10).until(lambda d: len(d.find_elements(By.CSS_SELECTOR, ''[class*=result], [class*=item], article'')) > 0
        or d.current_url != driver.current_url)
    results = driver.find_elements(By.CSS_SELECTOR, ''[class*=result], [class*=item], article'')
    assert len(results) > 0 or driver.current_url != driver.current_url, ''No search results appeared''

if __name__ == ''__main__'':
    driver = setup_driver()
    try:
        try:
            test_1_homepage_load_test(driver)
            print(''Test 1: PASSED'')
        except (AssertionError, Exception):
            print(''Test 1: FAILED'')
        try:
            test_2_navigation_links_test(driver)
            print(''Test 2: PASSED'')
        except (AssertionError, Exception):
            print(''Test 2: FAILED'')
        try:
            test_3_main_buttons_presence_test(driver)
            print(''Test 3: PASSED'')
        except (AssertionError, Exception):
            print(''Test 3: FAILED'')
        try:
            test_4_contact_form_detection_test(driver)
            print(''Test 4: PASSED'')
        except (AssertionError, Exception):
            print(''Test 4: FAILED'')
        try:
            test_5_form_submission_test(driver)
            print(''Test 5: PASSED'')
        except (AssertionError, Exception):
            print(''Test 5: FAILED'')
        try:
            test_6_images_and_sections_visibility_test(driver)
            print(''Test 6: PASSED'')
        except (AssertionError, Exception):
            print(''Test 6: FAILED'')
        try:
            test_7_search_with_valid_keyword_test(driver)
            print(''Test 7: PASSED'')
        except (AssertionError, Exception):
            print(''Test 7: FAILED'')
        try:
            test_8_search_with_empty_input_test(driver)
            print(''Test 8: PASSED'')
        except (AssertionError, Exception):
            print(''Test 8: FAILED'')
    finally:
        driver.quit()
