INSERT INTO public.generations (id, user_id, url, framework, status, test_cases, script, load_time_ms, is_spa, created_at, updated_at, script_selenium, script_cypress, test_cases_selenium, test_cases_cypress, pass_count, fail_count, skip_count, pass_rate, execution_results, page_type, scraped, script_playwright, test_type, project_id, performance_data, result) VALUES (220, 4, 'https://books.toscrape.com', 'Selenium', 'completed', '[{"id":1,"name":"Verify Add to basket button is clickable","description":"Verify that Add to basket button is clickable","preconditions":"Browser open, page accessible","steps":["Click on Add to basket button","Verify that button is clickable"],"test_data":[],"expected":"Button is clickable","type":"positive","priority":"high","category":"functional"},{"id":2,"name":"Verify page load time is less than 5 seconds","description":"Verify that page load time is less than 5 seconds","preconditions":"Browser open, page accessible","steps":["Load the page","Verify page load time"],"test_data":[],"expected":"Page load time is less than 5 seconds","type":"performance","priority":"high","category":"performance"},{"id":3,"name":"Verify Books to Scrape link is clickable","description":"Verify that Books to Scrape link is clickable","preconditions":"Browser open, page accessible","steps":["Click on Books to Scrape link","Verify that link is clickable"],"test_data":[],"expected":"Link is clickable","type":"positive","priority":"high","category":"navigation"},{"id":4,"name":"Verify image is loaded","description":"Verify that image is loaded","preconditions":"Browser open, page accessible","steps":["Verify image is loaded"],"test_data":[],"expected":"Image is loaded","type":"positive","priority":"medium","category":"ui"},{"id":5,"name":"Verify error message is visible","description":"Verify that error message is visible","preconditions":"Browser open, page accessible","steps":["Verify error message is visible"],"test_data":[],"expected":"Error message is visible","type":"positive","priority":"low","category":"ui"},{"id":6,"name":"Verify form is submitted successfully","description":"Verify that form is submitted successfully","preconditions":"Browser open, page accessible","steps":["Submit the form","Verify form submission is successful"],"test_data":[],"expected":"Form submission is successful","type":"positive","priority":"high","category":"functional"},{"id":7,"name":"Verify alert message is visible","description":"Verify that alert message is visible","preconditions":"Browser open, page accessible","steps":["Verify alert message is visible"],"test_data":[],"expected":"Alert message is visible","type":"positive","priority":"low","category":"ui"}]', '
from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
from selenium.webdriver.chrome.options import Options
import time

def setup_driver():
    opts = Options()
    return webdriver.Chrome(options=opts)

def test_1(driver):
    driver.get(''https://books.toscrape.com'')
    assert driver.title != '''', ''Page title empty''

def test_2(driver):
    driver.get(''https://books.toscrape.com'')
    WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''.btn'')))
    btn = WebDriverWait(driver, 10).until(EC.element_to_be_clickable((By.CSS_SELECTOR, ''.btn'')))
    btn.click()
    WebDriverWait(driver, 5).until(lambda d: d.current_url != driver.current_url)
    assert driver.current_url != driver.current_url, ''Cart page not loaded''

def test_3(driver):
    driver.get(''https://books.toscrape.com'')
    WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.LINK_TEXT, ''Books to Scrape'')))
    link = driver.find_element(By.LINK_TEXT, ''Books to Scrape'')
    original = driver.current_url
    link.click()
    WebDriverWait(driver, 10).until(lambda d: d.current_url != original)
    assert driver.current_url != original, ''Navigation failed''

def test_4(driver):
    driver.get(''https://books.toscrape.com'')
    WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''img[alt="A Light in the Attic"]'')))
    img = WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''img[alt="A Light in the Attic"]'')))
    loaded = driver.execute_script(''return arguments[0].complete && arguments[0].naturalWidth > 0'', img)
    assert loaded, ''Image not loaded''

def test_5(driver):
    driver.get(''https://books.toscrape.com'')
    WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''#messages'')))
    error = WebDriverWait(driver, 10).until(EC.visibility_of_element_located((By.CSS_SELECTOR, ''#messages'')))
    assert error.is_displayed(), ''Error not visible''

def test_6(driver):
    driver.get(''https://books.toscrape.com'')
    WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''.form-horizontal'')))
    form = driver.find_element(By.CSS_SELECTOR, ''.form-horizontal'')
    assert form is not None and form.is_displayed(), ''Form not found or not visible''

def test_7(driver):
    driver.get(''https://books.toscrape.com'')
    start = time.time()
    driver.get(''https://books.toscrape.com'')
    elapsed = time.time() - start
    assert elapsed < 5, f''Page too slow: {elapsed:.2f}s''

if __name__ == ''__main__'':
    driver = setup_driver()
    try:
        try:
            test_1(driver)
            print(''Test 1: PASSED'')
            test_2(driver)
            print(''Test 2: PASSED'')
            test_3(driver)
            print(''Test 3: PASSED'')
            test_4(driver)
            print(''Test 4: PASSED'')
            test_5(driver)
            print(''Test 5: PASSED'')
            test_6(driver)
            print(''Test 6: PASSED'')
            test_7(driver)
            print(''Test 7: PASSED'')
        except (AssertionError, Exception):
            print(''Test: FAILED'')
    finally:
        driver.quit()
