INSERT INTO public.generations (id, user_id, url, framework, status, test_cases, script, load_time_ms, is_spa, created_at, updated_at, script_selenium, script_cypress, test_cases_selenium, test_cases_cypress, pass_count, fail_count, skip_count, pass_rate, execution_results, page_type, scraped, script_playwright, test_type, project_id, performance_data, result) VALUES (222, 4, 'https://rescat.tn/', 'Selenium', 'completed', '[{"id":1,"name":"Search form submission test","description":"Verifies that the search form can be submitted successfully","preconditions":"Browser open, page accessible","steps":["Enter search query in input[name=''s'']","Click input[type=''submit'']"],"test_data":{"search_query":"test"},"expected":"Page redirects to search results","type":"positive","priority":"high","category":"functional"},{"id":2,"name":"Checkbox selection test","description":"Verifies that checkboxes can be selected and deselected","preconditions":"Browser open, page accessible","steps":["Click [name=''asl_gen[]'']","Verify [name=''asl_gen[]''] is checked","Click [name=''asl_gen[]''] again","Verify [name=''asl_gen[]''] is unchecked"],"test_data":[],"expected":"Checkbox is checked and then unchecked","type":"positive","priority":"medium","category":"functional"},{"id":3,"name":"Navigation link test","description":"Verifies that navigation links redirect to correct pages","preconditions":"Browser open, page accessible","steps":["Click link with text ''FAQ''","Verify page title is ''FAQ''"],"test_data":[],"expected":"Page redirects to FAQ page","type":"positive","priority":"medium","category":"navigation"},{"id":4,"name":"Error message visibility test","description":"Verifies that error messages are displayed when form is submitted with invalid data","preconditions":"Browser open, page accessible","steps":["Enter invalid search query in input[name=''s'']","Click input[type=''submit'']","Verify error message is displayed"],"test_data":{"invalid_search_query":"invalid"},"expected":"Error message is displayed","type":"positive","priority":"high","category":"functional"},{"id":5,"name":"Page load time test","description":"Verifies that page load time is less than 5 seconds","preconditions":"Browser open, page accessible","steps":["Measure page load time"],"test_data":[],"expected":"Page load time is less than 5 seconds","type":"positive","priority":"high","category":"performance"},{"id":6,"name":"Image load test","description":"Verifies that images are loaded successfully","preconditions":"Browser open, page accessible","steps":["Verify img is loaded"],"test_data":[],"expected":"Image is loaded","type":"positive","priority":"low","category":"ui"},{"id":7,"name":"Button click test","description":"Verifies that buttons can be clicked successfully","preconditions":"Browser open, page accessible","steps":["Click .elementor-button","Verify page redirects to correct page"],"test_data":[],"expected":"Page redirects to correct page","type":"positive","priority":"medium","category":"functional"}]', '
from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
from selenium.webdriver.chrome.options import Options
import time

def setup_driver():
    opts = Options()
    return webdriver.Chrome(options=opts)

def test_1_search_form_submission(driver):
    driver.get(''https://rescat.tn/'')
    search_query = ''test''
    search_input = WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''[name=\''s\'']'')))
    search_input.send_keys(search_query)
    submit_button = WebDriverWait(driver, 10).until(EC.element_to_be_clickable((By.CSS_SELECTOR, ''input[type=\''submit\'']'')))
    submit_button.click()
    original = driver.current_url
    WebDriverWait(driver, 10).until(lambda d: d.current_url != original)
    assert driver.current_url != original, ''Search form submission failed''

def test_2_checkbox_selection(driver):
    driver.get(''https://rescat.tn/'')
    checkbox = WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''[name=\''asl_gen[]\'']'')))
    checkbox.click()
    assert checkbox.is_selected(), ''Checkbox not selected''
    checkbox.click()
    assert not checkbox.is_selected(), ''Checkbox not deselected''

def test_3_navigation_link(driver):
    driver.get(''https://rescat.tn/'')
    original = driver.current_url
    faq_link = WebDriverWait(driver, 10).until(EC.element_to_be_clickable((By.LINK_TEXT, ''FAQ'')))
    faq_link.click()
    WebDriverWait(driver, 10).until(lambda d: d.current_url != original)
    assert driver.current_url != original, ''Navigation link failed''

def test_4_error_message_visibility(driver):
    driver.get(''https://rescat.tn/'')
    invalid_search_query = ''invalid''
    search_input = WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''[name=\''s\'']'')))
    search_input.send_keys(invalid_search_query)
    submit_button = WebDriverWait(driver, 10).until(EC.element_to_be_clickable((By.CSS_SELECTOR, ''input[type=\''submit\'']'')))
    submit_button.click()
    error_message = WebDriverWait(driver, 10).until(EC.visibility_of_element_located((By.CSS_SELECTOR, ''#cute-alert-css'')))
    assert error_message.is_displayed(), ''Error message not displayed''

def test_5_page_load_time(driver):
    start = time.time()
    driver.get(''https://rescat.tn/'')
    elapsed = time.time() - start
    assert elapsed < 5, f''Page too slow: {elapsed:.2f}s''

def test_6_image_load(driver):
    driver.get(''https://rescat.tn/'')
    img = WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''img'')))
    loaded = driver.execute_script(''return arguments[0].complete && arguments[0].naturalWidth > 0'', img)
    assert loaded, ''Image not loaded''

def test_7_button_click(driver):
    driver.get(''https://rescat.tn/'')
    original = driver.current_url
    button = WebDriverWait(driver, 10).until(EC.element_to_be_clickable((By.CSS_SELECTOR, ''.elementor-button'')))
    button.click()
    WebDriverWait(driver, 10).until(lambda d: d.current_url != original)
    assert driver.current_url != original, ''Button click failed''

if __name__ == ''__main__'':
    driver = setup_driver()
    try:
        try:
            test_1_search_form_submission(driver)
            print(''Test 1: PASSED'')
        except (AssertionError, Exception):
            print(''Test 1: FAILED'')
        try:
            test_2_checkbox_selection(driver)
            print(''Test 2: PASSED'')
        except (AssertionError, Exception):
            print(''Test 2: FAILED'')
        try:
            test_3_navigation_link(driver)
            print(''Test 3: PASSED'')
        except (AssertionError, Exception):
            print(''Test 3: FAILED'')
        try:
            test_4_error_message_visibility(driver)
            print(''Test 4: PASSED'')
        except (AssertionError, Exception):
            print(''Test 4: FAILED'')
        try:
            test_5_page_load_time(driver)
            print(''Test 5: PASSED'')
        except (AssertionError, Exception):
            print(''Test 5: FAILED'')
        try:
            test_6_image_load(driver)
            print(''Test 6: PASSED'')
        except (AssertionError, Exception):
            print(''Test 6: FAILED'')
        try:
            test_7_button_click(driver)
            print(''Test 7: PASSED'')
        except (AssertionError, Exception):
            print(''Test 7: FAILED'')
    finally:
