\n\nexport let options = {\n  insecureSkipTLSVerify: true,\n  stages: [\n    { duration: ''30s'', target: 20 },\n    { duration: ''30s'', target: 40 },\n    { duration: ''30s'', target: 60 },\n    { duration: ''30s'', target: 80 },\n    { duration: ''30s'', target: 0 },\n  ],\n  thresholds: {\n    http_req_duration: [''p(95)<5000''],\n    http_req_failed: [''rate<0.15''],\n  },\n};\n\nexport default function () {\n  group(''ANPE - Tunisia Stress Test'', () => {\n    pages.forEach((page) => {\n      const url = `${baseUrl}${page}`;\n      const res = http.get(url, { headers: { ''Authorization'': `Bearer ${authToken}` } });\n      check(res, { ''status is 200 or 302'': (r) => r.status === 200 || r.status === 302 });\n    });\n    sleep(Math.random() * 2 + 1);\n  });\n}","spike":"import http from ''k6\/http'';\nimport { sleep, check, group } from ''k6'';\n\nexport let options = {\n  insecureSkipTLSVerify: true,\n  stages: [\n    { duration: \"10s\", target: 5 },\n    { duration: \"10s\", target: 100 },\n    { duration: \"10s\", target: 5 },\n    { duration: \"10s\", target: 100 },\n    { duration: \"10s\", target: 0 }\n  ],\n  thresholds: {\n    \"http_req_duration\": [\"p(95)<8000\"],\n    \"http_req_failed\": [\"rate<0.20\"]\n  }\n}\n\nexport default function () {\n  let urls = [\n    ''https:\/\/anpe.demopro.tn:10443\/dashboard'',\n    ''https:\/\/anpe.demopro.tn:10443\/statistiques'',\n    ''https:\/\/anpe.demopro.tn:10443\/reception'',\n    ''https:\/\/anpe.demopro.tn:10443\/outbox'',\n    ''https:\/\/anpe.demopro.tn:10443\/traitement_dossier_eie''\n  ];\n\n  group(''ANPE - Tunisia'', function () {\n    for (let i = 0; i < urls.length; i++) {\n      let url = urls[i];\n      let res = http.get(url, { headers: { ''Authorization'': ''Bearer '' } });\n      check(res, { ''status is 200 or 302'': (r) => r.status === 200 || r.status === 302 });\n    }\n  });\n\n  sleep(Math.random() * 2 + 1);\n}","soak":"import http from ''k6\/http'';\nimport { sleep, check, group } from ''k6'';\n\nexport let options = {\n  insecureSkipTLSVerify: true,\n  stages: [\n    { duration: \"1m\", target: 10 },\n    { duration: \"3m\", target: 10 },\n    { duration: \"30s\", target: 0 }\n  ],\n  thresholds: {\n    \"http_req_duration\": [\"p(95)<3000\"],\n    \"http_req_failed\": [\"rate<0.05\"]\n  }\n};\n\nexport default function () {\n  let urls = [\n    ''https:\/\/anpe.demopro.tn:10443\/dashboard'',\n    ''https:\/\/anpe.demopro.tn:10443\/statistiques'',\n    ''https:\/\/anpe.demopro.tn:10443\/reception'',\n    ''https:\/\/anpe.demopro.tn:10443\/outbox'',\n    ''https:\/\/anpe.demopro.tn:10443\/traitement_dossier_eie''\n  ];\n\n  group(''ANPE - Tunisia'', function () {\n    let url = urls[Math.floor(Math.random() * urls.length)];\n    let res = http.get(url, { headers: { ''Authorization'': ''Bearer '' } });\n    check(res, { ''status is 200 or 302'': (r) => r.status === 200 || r.status === 302 });\n  });\n\n  sleep(Math.random() * 2 + 1);\n}"}}');
INSERT INTO public.generations (id, user_id, url, framework, status, test_cases, script, load_time_ms, is_spa, created_at, updated_at, script_selenium, script_cypress, test_cases_selenium, test_cases_cypress, pass_count, fail_count, skip_count, pass_rate, execution_results, page_type, scraped, script_playwright, test_type, project_id, performance_data, result) VALUES (223, 4, 'https://rescat.tn/', 'Selenium', 'completed', '[{"id":1,"name":"Search form submission test","description":"Verifies that the search form can be submitted successfully","preconditions":"Browser open, page accessible","steps":["Enter search query in input field with css_selector ''[name=''s'']''","Click submit button with css_selector ''input[type=''submit'']''"],"test_data":{"search_query":"test"},"expected":"Page redirects to search results page","type":"positive","priority":"high","category":"functional"},{"id":2,"name":"Checkbox selection test","description":"Verifies that checkboxes can be selected and deselected","preconditions":"Browser open, page accessible","steps":["Select checkbox with css_selector ''[name=''asl_gen[]'']''","Deselect checkbox with css_selector ''[name=''asl_gen[]'']''"],"test_data":[],"expected":"Checkbox is selected and then deselected","type":"positive","priority":"medium","category":"functional"},{"id":3,"name":"Navigation link test","description":"Verifies that navigation links are clickable and redirect to correct pages","preconditions":"Browser open, page accessible","steps":["Click link with text ''FAQ'' using By.LINK_TEXT"],"test_data":[],"expected":"Page redirects to FAQ page","type":"positive","priority":"medium","category":"navigation"},{"id":4,"name":"Error message visibility test","description":"Verifies that error messages are displayed when form is submitted with invalid data","preconditions":"Browser open, page accessible","steps":["Enter invalid search query in input field with css_selector ''[name=''s'']''","Click submit button with css_selector ''input[type=''submit'']''"],"test_data":{"search_query":"invalid"},"expected":"Error message is displayed with css_selector ''#cute-alert-css''","type":"positive","priority":"high","category":"functional"},{"id":5,"name":"Page load time test","description":"Verifies that page load time is less than 5 seconds","preconditions":"Browser open, page accessible","steps":["Measure page load time"],"test_data":[],"expected":"Page load time is less than 5 seconds","type":"positive","priority":"high","category":"performance"},{"id":6,"name":"Image loading test","description":"Verifies that images are loaded successfully","preconditions":"Browser open, page accessible","steps":["Verify image is loaded with css_selector ''img[alt=''logo-pirc'']''"],"test_data":[],"expected":"Image is loaded and visible","type":"positive","priority":"low","category":"ui"},{"id":7,"name":"Button click test","description":"Verifies that buttons are clickable and trigger correct actions","preconditions":"Browser open, page accessible","steps":["Click button with text ''Connexion'' using css_selector ''.elementor-button''"],"test_data":[],"expected":"Button click triggers correct action","type":"positive","priority":"medium","category":"functional"}]', '
from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
from selenium.webdriver.chrome.options import Options

def setup_driver():
    opts = Options()
    return webdriver.Chrome(options=opts)

def test_1_search_form_submission(driver):
    driver.get(''https://rescat.tn/'')
    search_query = ''test''
    search_input = WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''[name=\''s\'']'')))
    search_input.send_keys(search_query)
    submit_button = WebDriverWait(driver, 10).until(EC.element_to_be_clickable((By.CSS_SELECTOR, ''input[type=\''submit\'']'')))
    submit_button.click()
    original = driver.current_url
    WebDriverWait(driver, 10).until(lambda d: d.current_url != original)
    assert driver.current_url != original, ''Search form submission failed''

def test_2_checkbox_selection(driver):
    driver.get(''https://rescat.tn/'')
    checkbox = WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''[name=\''asl_gen[]\'']'')))
    checkbox.click()
    assert checkbox.is_selected(), ''Checkbox not selected''
    checkbox.click()
    assert not checkbox.is_selected(), ''Checkbox not deselected''

def test_3_navigation_link(driver):
    driver.get(''https://rescat.tn/'')
    original = driver.current_url
    link = WebDriverWait(driver, 10).until(EC.element_to_be_clickable((By.LINK_TEXT, ''FAQ'')))
    link.click()
    WebDriverWait(driver, 10).until(lambda d: d.current_url != original)
    assert driver.current_url != original, ''Navigation link failed''

def test_4_error_message_visibility(driver):
    driver.get(''https://rescat.tn/'')
    search_query = ''invalid''
    search_input = WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''[name=\''s\'']'')))
    search_input.send_keys(search_query)
    submit_button = WebDriverWait(driver, 10).until(EC.element_to_be_clickable((By.CSS_SELECTOR, ''input[type=\''submit\'']'')))
    submit_button.click()
    error_message = WebDriverWait(driver, 10).until(EC.visibility_of_element_located((By.CSS_SELECTOR, ''#cute-alert-css'')))
    assert error_message.is_displayed(), ''Error message not displayed''

def test_5_page_load_time(driver):
    import time
    start = time.time()
    driver.get(''https://rescat.tn/'')
    elapsed = time.time() - start
    assert elapsed < 5, f''Page load time too long: {elapsed:.2f}s''

def test_6_image_loading(driver):
    driver.get(''https://rescat.tn/'')
    img = WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''img[alt=\''logo-pirc\'']'')))
    loaded = driver.execute_script(''return arguments[0].complete && arguments[0].naturalWidth > 0'', img)
    assert loaded, ''Image not loaded''

def test_7_button_click(driver):
    driver.get(''https://rescat.tn/'')
    button = WebDriverWait(driver, 10).until(EC.element_to_be_clickable((By.CSS_SELECTOR, ''.elementor-button'')))
    button.click()
    assert True, ''Button click failed''

if __name__ == ''__main__'':
    driver = setup_driver()
    try:
        try:
            test_1_search_form_submission(driver)
            print(''Test 1: PASSED'')
        except (AssertionError, Exception):
            print(''Test 1: FAILED'')
        try:
            test_2_checkbox_selection(driver)
            print(''Test 2: PASSED'')
        except (AssertionError, Exception):
            print(''Test 2: FAILED'')
        try:
            test_3_navigation_link(driver)
            print(''Test 3: PASSED'')
        except (AssertionError, Exception):
            print(''Test 3: FAILED'')
        try:
            test_4_error_message_visibility(driver)
            print(''Test 4: PASSED'')
        except (AssertionError, Exception):
            print(''Test 4: FAILED'')
        try:
            test_5_page_load_time(driver)
            print(''Test 5: PASSED'')
        except (AssertionError, Exception):
            print(''Test 5: FAILED'')
        try:
            test_6_image_loading(driver)
            print(''Test 6: PASSED'')
        except (AssertionError, Exception):
            print(''Test 6: FAILED'')
        try:
            test_7_button_click(driver)
            print(''Test 7: PASSED'')
        except (AssertionError, Exception):
            print(''Test 7: FAILED'')
    finally:
        driver.quit()
