INSERT INTO public.generations (id, user_id, url, framework, status, test_cases, script, load_time_ms, is_spa, created_at, updated_at, script_selenium, script_cypress, test_cases_selenium, test_cases_cypress, pass_count, fail_count, skip_count, pass_rate, execution_results, page_type, scraped, script_playwright, test_type, project_id, performance_data, result) VALUES (225, 4, 'https://rescat.tn/', 'Selenium', 'completed', '[{"id":1,"name":"Homepage load test","description":"Verifies the homepage loads within 5 seconds","preconditions":"Browser open, page accessible","steps":["Open the page","Wait for page load"],"test_data":[],"expected":"Page load time is less than 5 seconds","type":"positive","priority":"high","category":"performance"},{"id":2,"name":"Navigation links test","description":"Verifies navigation links are present and clickable","preconditions":"Browser open, page accessible","steps":["Click on ''RESCAT'' link","Verify the page title is ''Accueil - RESCAT''"],"test_data":[],"expected":"Page title is ''Accueil - RESCAT''","type":"positive","priority":"medium","category":"navigation"},{"id":3,"name":"Main buttons presence test","description":"Verifies main buttons are present on the page","preconditions":"Browser open, page accessible","steps":["Verify ''Connexion'' button is present","Verify ''Start search'' button is present"],"test_data":[],"expected":"''Connexion'' and ''Start search'' buttons are present","type":"positive","priority":"medium","category":"ui"},{"id":4,"name":"Contact form detection test","description":"Verifies the contact form is present on the page","preconditions":"Browser open, page accessible","steps":["Verify the form with action ''https:\/\/rescat.tn\/'' is present"],"test_data":[],"expected":"Form with action ''https:\/\/rescat.tn\/'' is present","type":"positive","priority":"medium","category":"functional"},{"id":5,"name":"Form submission test","description":"Verifies the form can be submitted successfully","preconditions":"Browser open, page accessible","steps":["Fill in the form with valid data","Submit the form"],"test_data":[],"expected":"Form is submitted successfully","type":"positive","priority":"high","category":"functional"},{"id":6,"name":"Images and sections visibility test","description":"Verifies images and sections are visible on the page","preconditions":"Browser open, page accessible","steps":["Verify images are loaded and visible","Verify sections are visible"],"test_data":[],"expected":"Images and sections are visible","type":"positive","priority":"low","category":"ui"},{"id":7,"name":"Search with valid keyword test","description":"Verifies search with a valid keyword returns results","preconditions":"Browser open, page accessible","steps":["Enter a valid keyword in the search input","Submit the search form"],"test_data":{"search_keyword":"test"},"expected":"Search results are displayed","type":"positive","priority":"high","category":"functional"},{"id":8,"name":"Search with empty input test","description":"Verifies search with an empty input displays the placeholder or no change","preconditions":"Browser open, page accessible","steps":["Clear the search input","Submit the search form"],"test_data":[],"expected":"Placeholder is displayed or no change occurs","type":"positive","priority":"medium","category":"functional"}]', '
import time
from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
from selenium.webdriver.common.keys import Keys

def setup_driver():
    from selenium.webdriver.chrome.options import Options
    opts = Options()
    return webdriver.Chrome(options=opts)

def test_1_homepage_load_test(driver):
    start = time.time()
    driver.get(''https://rescat.tn/'')
    elapsed = time.time() - start
    assert elapsed < 5, f''Page too slow: {elapsed:.2f}s''

def test_2_navigation_links_test(driver):
    original = driver.current_url
    driver.find_element(By.LINK_TEXT, ''RESCAT'').click()
    WebDriverWait(driver, 10).until(lambda d: d.current_url != original)
    assert driver.current_url != original, ''Navigation failed''

def test_3_main_buttons_presence_test(driver):
    driver.get(''https://rescat.tn/'')
    connexion_button = WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''.elementor-button'')))
    start_search_button = WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''button'')))
    assert connexion_button is not None and connexion_button.is_displayed(), ''Connexion button not found or not visible''
    assert start_search_button is not None and start_search_button.is_displayed(), ''Start search button not found or not visible''

def test_4_contact_form_detection_test(driver):
    driver.get(''https://rescat.tn/'')
    form = WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''.hfe-search-button-wrapper'')))
    assert form is not None and form.is_displayed(), ''Form not found or not visible''

def test_5_form_submission_test(driver):
    driver.get(''https://rescat.tn/'')
    search_box = WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''[name=\''s\'']'')))
    search_box.clear()
    search_box.send_keys(''test keyword'')
    search_box.send_keys(Keys.RETURN)
    WebDriverWait(driver, 10).until(lambda d: len(d.find_elements(By.CSS_SELECTOR, ''[class*=result], [class*=item], article'')) > 0 or d.current_url != ''https://rescat.tn/'')
    results = driver.find_elements(By.CSS_SELECTOR, ''[class*=result], [class*=item], article'')
    assert len(results) > 0 or driver.current_url != ''https://rescat.tn/'', ''No search results appeared''

def test_6_images_and_sections_visibility_test(driver):
    driver.get(''https://rescat.tn/'')
    img = WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''img'')))
    loaded = driver.execute_script(''return arguments[0].complete && arguments[0].naturalWidth > 0'', img)
    assert loaded, ''Image not loaded''

def test_7_search_with_valid_keyword_test(driver):
    driver.get(''https://rescat.tn/'')
    search_box = WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''[name=\''s\'']'')))
    search_box.clear()
    search_box.send_keys(''test keyword'')
    search_box.send_keys(Keys.RETURN)
    WebDriverWait(driver, 10).until(lambda d: len(d.find_elements(By.CSS_SELECTOR, ''[class*=result], [class*=item], article'')) > 0 or d.current_url != ''https://rescat.tn/'')
    results = driver.find_elements(By.CSS_SELECTOR, ''[class*=result], [class*=item], article'')
    assert len(results) > 0 or driver.current_url != ''https://rescat.tn/'', ''No search results appeared''

def test_8_search_with_empty_input_test(driver):
    driver.get(''https://rescat.tn/'')
    search_box = WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''[name=\''s\'']'')))
    search_box.clear()
    search_box.send_keys(Keys.RETURN)
    WebDriverWait(driver, 10).until(lambda d: len(d.find_elements(By.CSS_SELECTOR, ''[class*=result], [class*=item], article'')) > 0 or d.current_url != ''https://rescat.tn/'')
    results = driver.find_elements(By.CSS_SELECTOR, ''[class*=result], [class*=item], article'')
    assert len(results) > 0 or driver.current_url != ''https://rescat.tn/'', ''No search results appeared''

if __name__ == ''__main__'':
    driver = setup_driver()
    try:
        try:
            test_1_homepage_load_test(driver)
            print(''Test 1: PASSED'')
        except (AssertionError, Exception):
            print(''Test 1: FAILED'')
        try:
            test_2_navigation_links_test(driver)
            print(''Test 2: PASSED'')
        except (AssertionError, Exception):
            print(''Test 2: FAILED'')
        try:
            test_3_main_buttons_presence_test(driver)
            print(''Test 3: PASSED'')
        except (AssertionError, Exception):
            print(''Test 3: FAILED'')
        try:
            test_4_contact_form_detection_test(driver)
            print(''Test 4: PASSED'')
        except (AssertionError, Exception):
            print(''Test 4: FAILED'')
        try:
            test_5_form_submission_test(driver)
            print(''Test 5: PASSED'')
        except (AssertionError, Exception):
            print(''Test 5: FAILED'')
        try:
            test_6_images_and_sections_visibility_test(driver)
            print(''Test 6: PASSED'')
        except (AssertionError, Exception):
            print(''Test 6: FAILED'')
        try:
            test_7_search_with_valid_keyword_test(driver)
            print(''Test 7: PASSED'')
        except (AssertionError, Exception):
            print(''Test 7: FAILED'')
        try:
            test_8_search_with_empty_input_test(driver)
            print(''Test 8: PASSED'')
        except (AssertionError, Exception):
            print(''Test 8: FAILED'')
    finally:
        driver.quit()
