def test_11_page_load_performance(driver):
  start = time.time()
  driver.get(''https://rescat.tn/'')
  WebDriverWait(driver, 30).until(EC.presence_of_element_located((By.TAG_NAME, ''body'')))
  elapsed = time.time() - start
  assert elapsed < 6, f''Page too slow: {elapsed:.2f}s''

def main():
  driver = setup_driver()
  tests = [test_1_page_load_and_title_check, test_2_navigation_test_faq, test_3_navigation_test_plan_du_site, test_4_navigation_test_glossaire, test_5_main_buttons_visibility, test_6_form_detection, test_7_form_submission, test_8_images_visibility, test_9_search_with_valid_keyword, test_10_search_with_empty_input, test_11_page_load_performance]
  passed = failed = 0
  try:
    for i, t in enumerate(tests, 1):
      try:
        t(driver)
        print(f''Test {i}: PASSED'')
        passed += 1
      except (AssertionError, Exception) as e:
        print(f''Test {i}: FAILED — {e}'')
        failed += 1
  finally:
    driver.quit()
    print(f''\n{passed} passed / {failed} failed'')

