ce of main buttons","preconditions":"Browser open, page accessible","steps":["Find the button with text ''Connexion''","Find the button with text ''X''","Find the button with text ''Menu''"],"test_data":[],"expected":"All buttons are present","type":"positive","priority":"low","category":"ui"},{"id":6,"name":"Search with Valid Keyword","description":"Verifies search functionality with a valid keyword","preconditions":"Browser open, page accessible","steps":["Enter a valid keyword in the search input","Submit the search form","Wait for the search results to load"],"test_data":{"keyword":"test"},"expected":"Search results are displayed","type":"positive","priority":"high","category":"functional"},{"id":7,"name":"Search with Empty Input","description":"Verifies search functionality with an empty input","preconditions":"Browser open, page accessible","steps":["Clear the search input","Submit the search form","Wait for the search results to load"],"test_data":[],"expected":"No search results are displayed","type":"positive","priority":"medium","category":"functional"},{"id":8,"name":"Images Visibility","description":"Verifies the visibility of images on the page","preconditions":"Browser open, page accessible","steps":["Find all images on the page","Check if each image is visible"],"test_data":[],"expected":"All images are visible","type":"positive","priority":"low","category":"ui"},{"id":9,"name":"Page Performance","description":"Verifies the page load time is within the expected threshold","preconditions":"Browser open, page accessible","steps":["Measure the page load time","Compare the load time to the threshold of 12 seconds"],"test_data":{"threshold":12},"expected":"Page load time is less than or equal to 12 seconds","type":"positive","priority":"high","category":"performance"}]', 'from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
from selenium.webdriver.common.keys import Keys
import time


def setup_driver():
  from selenium.webdriver.chrome.options import Options
  opts = Options()
  opts.page_load_strategy = ''normal''
  driver = webdriver.Chrome(options=opts)
  driver.set_page_load_timeout(30)
  driver.implicitly_wait(10)
  return driver


def test_1_page_load_and_title_check(driver):
  driver.get(''https://rescat.tn/'')
  WebDriverWait(driver, 30).until(EC.presence_of_element_located((By.TAG_NAME, ''body'')))
  assert driver.title != '''', ''Page title is empty''
  assert ''accueil'' in driver.title.lower(), f''Unexpected title: {driver.title}''


def test_2_navigation_test_faq(driver):
  original_url = driver.current_url
  driver.get(''https://rescat.tn/faq/'')
  WebDriverWait(driver, 30).until(lambda d: d.title != '''')
  assert driver.current_url != original_url, ''Navigation failed''


def test_3_navigation_test_plan_du_site(driver):
  original_url = driver.current_url
  driver.get(''https://rescat.tn/plan-du-site/'')
  WebDriverWait(driver, 30).until(lambda d: d.title != '''')
  assert driver.current_url != original_url, ''Navigation failed''


def test_4_navigation_test_glossaire(driver):
  original_url = driver.current_url
  driver.get(''https://rescat.tn/glossaire/'')
  WebDriverWait(driver, 30).until(lambda d: d.title != '''')
  assert driver.current_url != original_url, ''Navigation failed''


def test_5_main_buttons_presence(driver):
  el1 = WebDriverWait(driver, 30).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''.elementor-button'')))
  el2 = WebDriverWait(driver, 30).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''.elementskit-menu-close'')))
  el3 = WebDriverWait(driver, 30).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''.hfe-nav-menu__toggle'')))
  assert el1 is not None and el2 is not None and el3 is not None, ''Buttons not found''


def test_6_search_with_valid_keyword(driver):
  original_url = driver.current_url
  search_box = WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''[name="s"]'')))
  search_box.clear()
  search_box.send_keys(''test'')
  search_box.send_keys(Keys.RETURN)
  WebDriverWait(driver, 15).until(lambda d: d.current_url != original_url)
  assert driver.current_url != original_url, ''Search did not navigate''


def test_7_search_with_empty_input(driver):
  original_url = driver.current_url
  search_box = WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''[name="s"]'')))
  search_box.clear()
  search_box.send_keys(Keys.RETURN)
  time.sleep(2)
  placeholder = search_box.get_attribute(''placeholder'')
  assert driver.current_url == original_url or placeholder != '''', ''Unexpected behavior on empty search''


def test_8_images_visibility(driver):
  img = WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''img'')))
  loaded = driver.execute_script(''return arguments[0].complete && arguments[0].naturalWidth > 0'', img)
  assert loaded, ''Image not loaded''


def test_9_page_performance(driver):
  start = time.time()
  driver.get(''https://rescat.tn/'')
  WebDriverWait(driver, 30).until(EC.presence_of_element_located((By.TAG_NAME, ''body'')))
  elapsed = time.time() - start
  assert elapsed < 12, f''Page too slow: {elapsed:.2f}s''


def main():
  driver = setup_driver()
  tests = [test_1_page_load_and_title_check, test_2_navigation_test_faq, test_3_navigation_test_plan_du_site, test_4_navigation_test_glossaire, test_5_main_buttons_presence, test_6_search_with_valid_keyword, test_7_search_with_empty_input, test_8_images_visibility, test_9_page_performance]
  passed = failed = 0
  try:
    for i, t in enumerate(tests, 1):
      try:
        t(driver)
        print(f''Test {i}: PASSED'')
        passed += 1
      except (AssertionError, Exception) as e:
        print(f''Test {i}: FAILED — {e}'')
        failed += 1
  finally:
    driver.quit()
    print(f''
{passed} passed / {failed} failed'')

if __name__ == ''__main__'':
