ge title is not empty"],"test_data":[],"expected":"Page title is not empty","type":"positive","priority":"medium","category":"navigation"},{"id":5,"name":"Image Visibility","description":"Verifies the visibility of images on the page","preconditions":"Browser open, page accessible","steps":["Open the page https:\/\/rescat.tn\/","Verify the presence of images on the page"],"test_data":[],"expected":"Images are present on the page","type":"positive","priority":"low","category":"ui"},{"id":6,"name":"Page Performance","description":"Verifies the page load time is within the expected range","preconditions":"Browser open, page accessible","steps":["Open the page https:\/\/rescat.tn\/","Measure the page load time"],"test_data":[],"expected":"Page load time is less than 3000 ms","type":"positive","priority":"low","category":"performance"}]', 'from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
from selenium.webdriver.common.keys import Keys
import time

def setup_driver():
  from selenium.webdriver.chrome.options import Options
  opts = Options()
  opts.page_load_strategy = ''normal''
  driver = webdriver.Chrome(options=opts)
  driver.set_page_load_timeout(30)
  driver.implicitly_wait(10)
  return driver

def test_1_page_load(driver):
  driver.get(''https://rescat.tn/'')
  WebDriverWait(driver, 30).until(EC.presence_of_element_located((By.TAG_NAME, ''body'')))
  assert driver.title != '''', ''Page title is empty''
  assert ''accueil'' in driver.title.lower(), ''Unexpected title''

def test_2_faq_navigation(driver):
  driver.get(''https://rescat.tn/'')
  original_url = driver.current_url
  links = driver.find_elements(By.CSS_SELECTOR, ''a[href]'')
  target_href = next((l.get_attribute(''href'') for l in links if ''faq'' in (l.get_attribute(''href'') or '''') and l.get_attribute(''href'') != original_url and not (l.get_attribute(''href'') or '''').endswith(''#'')), None)
  assert target_href is not None, ''Target link not found''
  driver.get(target_href)
  WebDriverWait(driver, 30).until(lambda d: d.title != '''')
  assert ''faq'' in driver.current_url, ''Navigation to faq failed''

def test_3_plan_du_site_navigation(driver):
  driver.get(''https://rescat.tn/'')
  original_url = driver.current_url
  links = driver.find_elements(By.CSS_SELECTOR, ''a[href]'')
  target_href = next((l.get_attribute(''href'') for l in links if ''plan-du-site'' in (l.get_attribute(''href'') or '''') and l.get_attribute(''href'') != original_url and not (l.get_attribute(''href'') or '''').endswith(''#'')), None)
  assert target_href is not None, ''Target link not found''
  driver.get(target_href)
  WebDriverWait(driver, 30).until(lambda d: d.title != '''')
  assert ''plan-du-site'' in driver.current_url, ''Navigation to plan-du-site failed''

def test_4_glossaire_navigation(driver):
  driver.get(''https://rescat.tn/'')
  original_url = driver.current_url
  links = driver.find_elements(By.CSS_SELECTOR, ''a[href]'')
  target_href = next((l.get_attribute(''href'') for l in links if ''glossaire'' in (l.get_attribute(''href'') or '''') and l.get_attribute(''href'') != original_url and not (l.get_attribute(''href'') or '''').endswith(''#'')), None)
  assert target_href is not None, ''Target link not found''
  driver.get(target_href)
  WebDriverWait(driver, 30).until(lambda d: d.title != '''')
  assert ''glossaire'' in driver.current_url, ''Navigation to glossaire failed''

def test_5_image_visibility(driver):
  driver.get(''https://rescat.tn/'')
  img = WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.CSS_SELECTOR, ''img'')))
  loaded = driver.execute_script(''return arguments[0].complete && arguments[0].naturalWidth > 0'', img)
  assert loaded, ''Image not loaded''

def test_6_page_performance(driver):
  start = time.time()
  driver.get(''https://rescat.tn/'')
  WebDriverWait(driver, 30).until(EC.presence_of_element_located((By.TAG_NAME, ''body'')))
  elapsed = time.time() - start
  assert elapsed < 5, f''Page too slow: {elapsed:.2f}s''

def main():
  driver = setup_driver()
  tests = [test_1_page_load, test_2_faq_navigation, test_3_plan_du_site_navigation, test_4_glossaire_navigation, test_5_image_visibility, test_6_page_performance]
  passed = failed = 0
  try:
    for i, t in enumerate(tests, 1):
