def test_5_language_switcher__fr_(driver):
    driver.get(''https://rescat.tn/'')
    try:
        el = WebDriverWait(driver, 10).until(
            EC.presence_of_element_located((By.CSS_SELECTOR, ''a[href*=''#pll_switcher'']'')))
        assert el is not None
    except Exception:
        print(''[WARN] Optional element not found: a[href*=''#pll_switcher'']'')

def test_6_hero_section_present(driver):
    driver.get(''https://rescat.tn/'')
    try:
        el = WebDriverWait(driver, 10).until(
            EC.presence_of_element_located((By.CSS_SELECTOR, ''[class*=''hero''], [class*=''banner''], [class*=''jumbotron''], [class*=''slider'']'')))
