    driver.get(''https://rescat.tn/'')
    try:
        el = WebDriverWait(driver, 10).until(
            EC.presence_of_element_located((By.CSS_SELECTOR, ''img[src*=''final_logo_pirc_ar-1.png'']'')))
        assert el is not None
    except Exception:
        print(''[WARN] Optional element not found: img[src*=''final_logo_pirc_ar-1.png'']'')

