        expect(page.locator(''img[src*=''icon1.png'']'').first).to_be_visible(timeout=10000)
    except Exception:
        pytest.skip(''Optional element not found: img[src*=''icon1.png'']'')

def test_footer_present(page):
    try:
        expect(page.locator(''footer, [class*=''footer''], #footer'').first).to_be_visible(timeout=10000)
    except Exception:
        pytest.skip(''Optional element not found: footer, [class*=''footer''], #footer'')
