import pytest, re

BASE_URL = ''https://rescat.tn/''

@pytest.fixture(scope=''module'')
def page():
    with sync_playwright() as p:
        browser = p.chromium.launch(headless=True)
        ctx = browser.new_context(viewport={''width'': 1920, ''height'': 1080})
        pg  = ctx.new_page()
        pg.goto(BASE_URL, wait_until=''domcontentloaded'')
        yield pg
        browser.close()

def test_main_navigation_present(page):
    expect(page.locator(''nav, [class*=''navbar''], [class*=''nav-bar''], header nav'').first).to_be_visible(timeout=15000)

def test_main_content_area_present(page):
    expect(page.locator(''main, [role=''main''], #main, #content, .main-content'').first).to_be_visible(timeout=15000)

def test_page_title__h1__present(page):
    expect(page.locator(''h1'').first).to_be_visible(timeout=15000)

def test_search_bar__if_present_(page):
    try:
        expect(page.locator(''form[role=''search''], form[action*=''search''], [class*=''search-form''], [class*=''searchform''], [id*=''search-form''], [id*=''searchform''], [class*=''search-bar''], [class*=''search-box''], input[type=''search''], input[name=''s''], input[placeholder*=''search'' i], input[placeholder*=''recherche'' i], input[placeholder*=''chercher'' i], input[placeholder*=''بحث'' i]'').first).to_be_visible(timeout=10000)
    except Exception:
        pytest.skip(''Optional element not found: form[role=''search''], form[action*=''search''], [class*=''search-form''], [class*=''searchform''], [id*=''search-form''], [id*=''searchform''], [class*=''search-bar''], [class*=''search-box''], input[type=''search''], input[name=''s''], input[placeholder*=''search'' i], input[placeholder*=''recherche'' i], input[placeholder*=''chercher'' i], input[placeholder*=''بحث'' i]'')

def test_language_switcher__fr_(page):
    try:
        expect(page.locator(''a[href*=''#pll_switcher'']'').first).to_be_visible(timeout=10000)
    except Exception:
        pytest.skip(''Optional element not found: a[href*=''#pll_switcher'']'')

def test_hero_section_present(page):
    try:
        expect(page.locator(''[class*=''hero''], [class*=''banner''], [class*=''jumbotron''], [class*=''slider'']'').first).to_be_visible(timeout=10000)
    except Exception:
        pytest.skip(''Optional element not found: [class*=''hero''], [class*=''banner''], [class*=''jumbotron''], [class*=''slider'']'')

def test_brand_logo_present(page):
    try:
        expect(page.locator(''img[alt*=''logo'' i], img[src*=''logo'' i], [class*=''logo''] img, .logo img, .navbar-brand img, [class*=''logo''] svg, header [class*=''brand'']'').first).to_be_visible(timeout=10000)
    except Exception:
        pytest.skip(''Optional element not found: img[alt*=''logo'' i], img[src*=''logo'' i], [class*=''logo''] img, .logo img, .navbar-brand img, [class*=''logo''] svg, header [class*=''brand'']'')

