    driver.get(''https://rescat.tn/'')
    el = WebDriverWait(driver, 15).until(
        EC.presence_of_element_located((By.CSS_SELECTOR, ''img[alt*=''logo'' i], img[src*=''logo'' i], [class*=''logo''] img, .logo img, .navbar-brand img'')))
    assert el is not None, ''Element not found: img[alt*=''logo'' i], img[src*=''logo'' i], [class*=''logo''] img, .logo img, .navbar-brand img''

