from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
from selenium.webdriver.chrome.options import Options
import time

def setup_driver():
    opts = Options()
    opts.add_argument(''--headless'')
    opts.add_argument(''--no-sandbox'')
    opts.add_argument(''--disable-dev-shm-usage'')
    opts.add_argument(''--window-size=1920,1080'')
    driver = webdriver.Chrome(options=opts)
    driver.set_page_load_timeout(30)
    driver.implicitly_wait(10)
    return driver

def test_1_page_body_visible(driver):
    driver.get(''https://rescat.tn/'')
    el = WebDriverWait(driver, 15).until(
        EC.presence_of_element_located((By.CSS_SELECTOR, ''body'')))
    assert el is not None, ''Element not found: body''

def test_2_page_heading_visible(driver):
    driver.get(''https://rescat.tn/'')
    el = WebDriverWait(driver, 15).until(
        EC.presence_of_element_located((By.CSS_SELECTOR, ''h1, h2, h3'')))
    assert el is not None, ''Element not found: h1, h2, h3''

def test_3_main_content_area_visible(driver):
    driver.get(''https://rescat.tn/'')
    el = WebDriverWait(driver, 15).until(
        EC.presence_of_element_located((By.CSS_SELECTOR, ''main, [role=''main''], #main, #content'')))
    assert el is not None, ''Element not found: main, [role=''main''], #main, #content''

def test_4_navigation_present(driver):
    driver.get(''https://rescat.tn/'')
    try:
        el = WebDriverWait(driver, 10).until(
            EC.presence_of_element_located((By.CSS_SELECTOR, ''nav, header nav'')))
        assert el is not None
    except Exception:
        print(''[WARN] Optional element not found: nav, header nav'')

def test_5_pagination_present(driver):
    driver.get(''https://rescat.tn/'')
    try:
        el = WebDriverWait(driver, 10).until(
            EC.presence_of_element_located((By.CSS_SELECTOR, ''.pagination a, [class*=''pagination''] a, [class*=''page-item''] a'')))
        assert el is not None
    except Exception:
        print(''[WARN] Optional element not found: .pagination a, [class*=''pagination''] a, [class*=''page-item''] a'')

if __name__ == ''__main__'':
