def test_pagination_present(page):
    try:
        expect(page.locator(''.pagination a, [class*=''pagination''] a, [class*=''page-item''] a, .pager a, [class*=''pager''] a, a[rel=''next''], a[rel=''prev'']'').first).to_be_visible(timeout=10000)
