import pytest, re

BASE_URL = ''https://rescat.tn/''

@pytest.fixture(scope=''module'')
def page():
    with sync_playwright() as p:
        browser = p.chromium.launch(headless=True)
        ctx = browser.new_context(viewport={''width'':1920,''height'':1080})
        pg = ctx.new_page()
        pg.goto(BASE_URL, wait_until=''domcontentloaded'')
        yield pg
        browser.close()

def test_page_body_rendered(page):
    expect(page.locator(''body'').first).to_be_visible(timeout=15000)

def test_page_heading_visible(page):
    expect(page.locator(''h1, h2, h3'').first).to_be_visible(timeout=15000)

def test_main_content_area_present(page):
    expect(page.locator(''main, [role=''main''], #content, .content, article'').first).to_be_visible(timeout=15000)

def test_navigation_present(page):
    try: expect(page.locator(''a[href*=''faq'']'').first).to_be_visible(timeout=10000)
    except Exception: pytest.skip(''Optional: a[href*=''faq'']'')

def test_nav_link__plan_du_site(page):
    try: expect(page.locator(''a[href*=''plan-du-site'']'').first).to_be_visible(timeout=10000)
    except Exception: pytest.skip(''Optional: a[href*=''plan-du-site'']'')

def test_nav_link__glossaire(page):
    try: expect(page.locator(''a[href*=''glossaire'']'').first).to_be_visible(timeout=10000)
    except Exception: pytest.skip(''Optional: a[href*=''glossaire'']'')

def test_nav_link__fr(page):
    try: expect(page.locator(''a[href*=''#pll_switcher'']'').first).to_be_visible(timeout=10000)
    except Exception: pytest.skip(''Optional: a[href*=''#pll_switcher'']'')

def test_brand_logo_visible(page):
    try: expect(page.locator(''img[src*=''final_logo_pirc_ar-1.png'']'').first).to_be_visible(timeout=10000)
    except Exception: pytest.skip(''Optional: img[src*=''final_logo_pirc_ar-1.png'']'')
