ed":false,"error":"\u26a0 69KB between 50KB (good) and 150KB (poor)"}},{"id":9,"name":"\ud83c\udfa8 CSS Stylesheets Size","action":"measure","selector":"link[rel=stylesheet]","value":"35 KB","status":"fail","duration":"\u2014","category":"performance","priority":"medium","section":"assets","optional":false,"description":"\u26a0 35KB between 20KB (good) and 50KB (poor)","suite":"\u26a0 35KB between 20KB (good) and 50KB (poor)","base_url":"https:\/\/books.toscrape.com\/","metric_key":"css_size_kb","metric_value":35,"metric_unit":"KB","metric_good":20,"metric_poor":50,"metric_score":45,"assertion":{"type":"performance_threshold","expected":"\u2264 20KB","actual":"35 KB","passed":false,"error":"\u26a0 35KB between 20KB (good) and 50KB (poor)"}},{"id":10,"name":"\ud83d\uddbc Images Total Size","action":"measure","selector":"img","value":"179 KB","status":"fail","duration":"\u2014","category":"performance","priority":"medium","section":"assets","optional":false,"description":"\u26a0 179KB between 100KB (good) and 250KB (poor)","suite":"\u26a0 179KB between 100KB (good) and 250KB (poor)","base_url":"https:\/\/books.toscrape.com\/","metric_key":"image_size_kb","metric_value":179,"metric_unit":"KB","metric_good":100,"metric_poor":250,"metric_score":42,"assertion":{"type":"performance_threshold","expected":"\u2264 100KB","actual":"179 KB","passed":false,"error":"\u26a0 179KB between 100KB (good) and 250KB (poor)"}}]', 'from playwright.sync_api import sync_playwright
import pytest, time

BASE_URL = ''https://books.toscrape.com/''

def get_metrics(page):
    page.goto(BASE_URL, wait_until=''networkidle'')
    return page.evaluate(''''''() => {
        const nav = performance.getEntriesByType(''navigation'')[0] || {};
        const resources = performance.getEntriesByType(''resource'');
        const paintEntries = performance.getEntriesByType(''paint'');
        const fcp = paintEntries.find(e => e.name === ''first-contentful-paint'');
        return {
            load_time_ms:  Math.round(nav.loadEventEnd || 0),
            fcp_ms:        Math.round(fcp ? fcp.startTime : 0),
            lcp_ms:        Math.round(nav.domContentLoadedEventEnd || 0),
            request_count: resources.length,
            dom_size:      document.querySelectorAll(''*'').length,
            total_size_kb: Math.round(resources.reduce((s,r) => s + (r.transferSize||0), 0) / 1024),
        };
    }'''''')

@pytest.fixture(scope=''module'')
def metrics():
    with sync_playwright() as p:
        browser = p.chromium.launch(headless=True)
        page = browser.new_page()
        m = get_metrics(page)
        browser.close()
        return m

def test_load_time_ms(metrics):
    value = metrics.get(''load_time_ms'')
    if not value:
        pytest.skip(''Page Load Time not measurable'')
    assert value <= 3000, f''Page Load Time: {value}ms exceeds 3000ms''

def test_fcp_ms(metrics):
    value = metrics.get(''fcp_ms'')
    if not value:
        pytest.skip(''First Contentful Paint not measurable'')
    assert value <= 2000, f''First Contentful Paint: {value}ms exceeds 2000ms''

def test_lcp_ms(metrics):
    value = metrics.get(''lcp_ms'')
    if not value:
        pytest.skip(''Largest Contentful Paint not measurable'')
    assert value <= 2500, f''Largest Contentful Paint: {value}ms exceeds 2500ms''

def test_tti_ms(metrics):
    value = metrics.get(''tti_ms'')
    if not value:
        pytest.skip(''Time to Interactive not measurable'')
    assert value <= 3500, f''Time to Interactive: {value}ms exceeds 3500ms''

def test_request_count(metrics):
    value = metrics.get(''request_count'')
    if not value:
        pytest.skip(''Network Requests not measurable'')
    assert value <= 40, f''Network Requests: {value} exceeds 40''

def test_total_size_kb(metrics):
    value = metrics.get(''total_size_kb'')
    if not value:
        pytest.skip(''Total Resource Size not measurable'')
    assert value <= 250, f''Total Resource Size: {value}KB exceeds 250KB''

def test_dom_size(metrics):
    value = metrics.get(''dom_size'')
    if not value:
        pytest.skip(''DOM Elements not measurable'')
    assert value <= 500, f''DOM Elements: {value} exceeds 500''

def test_js_size_kb(metrics):
    value = metrics.get(''js_size_kb'')
    if not value:
        pytest.skip(''JavaScript Size not measurable'')
    assert value <= 50, f''JavaScript Size: {value}KB exceeds 50KB''

def test_css_size_kb(metrics):
    value = metrics.get(''css_size_kb'')
    if not value:
        pytest.skip(''CSS Size not measurable'')
    assert value <= 20, f''CSS Size: {value}KB exceeds 20KB''

def test_image_size_kb(metrics):
    value = metrics.get(''image_size_kb'')
    if not value:
        pytest.skip(''Images Size not measurable'')
    assert value <= 100, f''Images Size: {value}KB exceeds 100KB''
