            request_count: resources.length,
            dom_size:      document.querySelectorAll(''*'').length,
            total_size_kb: Math.round(resources.reduce((s,r) => s + (r.transferSize||0), 0) / 1024),
        };
    }'''''')

@pytest.fixture(scope=''module'')
def metrics():
    with sync_playwright() as p:
        browser = p.chromium.launch(headless=True)
        page = browser.new_page()
        m = get_metrics(page)
        browser.close()
        return m

def test_load_time_ms(metrics):
    value = metrics.get(''load_time_ms'')
    if not value:
        pytest.skip(''Page Load Time not measurable'')
    assert value <= 2500, f''Page Load Time: {value}ms exceeds 2500ms''

def test_fcp_ms(metrics):
    value = metrics.get(''fcp_ms'')
    if not value:
        pytest.skip(''First Contentful Paint not measurable'')
    assert value <= 1600, f''First Contentful Paint: {value}ms exceeds 1600ms''

def test_lcp_ms(metrics):
    value = metrics.get(''lcp_ms'')
    if not value:
        pytest.skip(''Largest Contentful Paint not measurable'')
    assert value <= 2800, f''Largest Contentful Paint: {value}ms exceeds 2800ms''

def test_tti_ms(metrics):
    value = metrics.get(''tti_ms'')
    if not value:
        pytest.skip(''Time to Interactive not measurable'')
    assert value <= 3200, f''Time to Interactive: {value}ms exceeds 3200ms''

def test_request_count(metrics):
    value = metrics.get(''request_count'')
    if not value:
        pytest.skip(''Network Requests not measurable'')
    assert value <= 60, f''Network Requests: {value} exceeds 60''

def test_total_size_kb(metrics):
    value = metrics.get(''total_size_kb'')
    if not value:
        pytest.skip(''Total Resource Size not measurable'')
    assert value <= 2000, f''Total Resource Size: {value}KB exceeds 2000KB''

def test_dom_size(metrics):
    value = metrics.get(''dom_size'')
    if not value:
        pytest.skip(''DOM Elements not measurable'')
    assert value <= 1200, f''DOM Elements: {value} exceeds 1200''

def test_js_size_kb(metrics):
    value = metrics.get(''js_size_kb'')
    if not value:
        pytest.skip(''JavaScript Size not measurable'')
    assert value <= 600, f''JavaScript Size: {value}KB exceeds 600KB''

def test_css_size_kb(metrics):
    value = metrics.get(''css_size_kb'')
    if not value:
        pytest.skip(''CSS Size not measurable'')
    assert value <= 200, f''CSS Size: {value}KB exceeds 200KB''

def test_image_size_kb(metrics):
    value = metrics.get(''image_size_kb'')
    if not value:
        pytest.skip(''Images Size not measurable'')
    assert value <= 1500, f''Images Size: {value}KB exceeds 1500KB''
