"has_alt":true,"is_decorative":false,"loaded":true,"in_viewport":true,"width":409,"height":300},{"css_selector":"img[src*=''9-300x225.jpg'']","src":"https:\/\/rescat.tn\/wp-content\/uploads\/2026\/04\/9-300x225.jpg","alt":"L\u2019\u00e9laboration et \u00e0 la mise en \u0153uvre des Plans de Gestion Environnementale et Sociale (PGES)","has_alt":true,"is_decorative":false,"loaded":true,"in_viewport":true,"width":409,"height":300}],"icons":[],"input_fields":[],"footer_data":[],"content_sections":[],"headings":[],"cards":[]}', 'from playwright.sync_api import sync_playwright
import pytest, time

BASE_URL = ''https://rescat.tn/''

def get_metrics(page):
    page.goto(BASE_URL, wait_until=''networkidle'')
    return page.evaluate(''''''() => {
        const nav = performance.getEntriesByType(''navigation'')[0] || {};
        const resources = performance.getEntriesByType(''resource'');
        const paintEntries = performance.getEntriesByType(''paint'');
        const fcp = paintEntries.find(e => e.name === ''first-contentful-paint'');
        return {
            load_time_ms:  Math.round(nav.loadEventEnd || 0),
            fcp_ms:        Math.round(fcp ? fcp.startTime : 0),
            lcp_ms:        Math.round(nav.domContentLoadedEventEnd || 0),
            request_count: resources.length,
            dom_size:      document.querySelectorAll(''*'').length,
            total_size_kb: Math.round(resources.reduce((s,r) => s + (r.transferSize||0), 0) / 1024),
        };
    }'''''')

@pytest.fixture(scope=''module'')
def metrics():
    with sync_playwright() as p:
        browser = p.chromium.launch(headless=True)
        page = browser.new_page()
        m = get_metrics(page)
        browser.close()
        return m

def test_load_time_ms(metrics):
    value = metrics.get(''load_time_ms'')
    if not value:
        pytest.skip(''Page Load Time not measurable'')
    assert value <= 2500, f''Page Load Time: {value}ms exceeds 2500ms''

def test_fcp_ms(metrics):
    value = metrics.get(''fcp_ms'')
    if not value:
        pytest.skip(''First Contentful Paint not measurable'')
    assert value <= 1600, f''First Contentful Paint: {value}ms exceeds 1600ms''

def test_lcp_ms(metrics):
    value = metrics.get(''lcp_ms'')
    if not value:
        pytest.skip(''Largest Contentful Paint not measurable'')
    assert value <= 2800, f''Largest Contentful Paint: {value}ms exceeds 2800ms''

def test_tti_ms(metrics):
