    expect(page.locator(''img[src*=''final_logo_pirc_ar-1.png'']'').first).to_be_visible(timeout=15000)

def test_verify_faq_url(page):
    expect(page.locator(''N/A'').first).to_be_visible(timeout=15000)

def test_return_to_homepage(page):
    page.locator(''a[href=''/'']'').first.click()
    page.wait_for_load_state(''domcontentloaded'')
    expect(page.locator(''a[href=''/'']'').first).to_be_visible(timeout=15000)
