omepage loaded","optional":false}]', 'from playwright.sync_api import sync_playwright, expect
import pytest, re

BASE_URL = ''https://rescat.tn/''

@pytest.fixture(scope=''module'')
def page():
    with sync_playwright() as p:
        browser = p.chromium.launch(headless=True)
        ctx = browser.new_context(viewport={''width'':1920,''height'':1080})
        pg = ctx.new_page()
        pg.goto(BASE_URL, wait_until=''domcontentloaded'')
        yield pg
        browser.close()

def test_check_faq_link_visibility(page):
    expect(page.locator(''a[href*=''faq'']'').first).to_be_visible(timeout=15000)

def test_click_faq_link(page):
    page.locator(''a[href*=''faq'']'').first.click()
    page.wait_for_load_state(''domcontentloaded'')
    expect(page).to_have_url(re.compile(r''faq''))

def test_check_plan_du_site_link_visibility(page):
    expect(page.locator(''a[href*=''plan-du-site'']'').first).to_be_visible(timeout=15000)

def test_click_plan_du_site_link(page):
    page.locator(''a[href*=''plan-du-site'']'').first.click()
    page.wait_for_load_state(''domcontentloaded'')
    expect(page).to_have_url(re.compile(r''plan\-du\-site''))

def test_check_glossaire_link_visibility(page):
    expect(page.locator(''a[href*=''glossaire'']'').first).to_be_visible(timeout=15000)

def test_click_glossaire_link(page):
    page.locator(''a[href*=''glossaire'']'').first.click()
    page.wait_for_load_state(''domcontentloaded'')
    expect(page).to_have_url(re.compile(r''glossaire''))

def test_check_fr_link_visibility(page):
    expect(page.locator(''a[href*=''#pll_switcher'']'').first).to_be_visible(timeout=15000)

def test_click_fr_link(page):
    page.locator(''a[hreflang=''fr'']'').first.click()
    page.wait_for_load_state(''domcontentloaded'')
    expect(page).to_have_url(re.compile(r''fr''))

def test_check_ar_link_visibility(page):
    expect(page.locator(''a[href*=''%d8%a7%d9%84%d8%a7%d8%b3%d8%aa%d9%82%d8%a8%d8%a7%d9%84'']'').first).to_be_visible(timeout=15000)

def test_click_ar_link(page):
    page.locator(''a[hreflang=''ar'']'').first.click()
    page.wait_for_load_state(''domcontentloaded'')
    expect(page).to_have_url(re.compile(r''ar''))

def test_check_en_link_visibility(page):
    expect(page.locator(''a[href*=''home'']'').first).to_be_visible(timeout=15000)

def test_click_en_link(page):
    page.locator(''a[hreflang=''en'']'').first.click()
    page.wait_for_load_state(''domcontentloaded'')
    expect(page).to_have_url(re.compile(r''en''))

def test_check_logo_visibility(page):
    expect(page.locator(''img[src*=''final_logo_pirc_ar-1.png'']'').first).to_be_visible(timeout=15000)

def test_verify_faq_url(page):
    expect(page.locator(''N/A'').first).to_be_visible(timeout=15000)

def test_return_to_homepage(page):
    page.locator(''a[href=''/'']'').first.click()
    page.wait_for_load_state(''domcontentloaded'')
    expect(page.locator(''a[href=''/'']'').first).to_be_visible(timeout=15000)
