import pytest, re

BASE_URL = ''https://rescat.tn/''

@pytest.fixture(scope=''module'')
def page():
    with sync_playwright() as p:
        browser = p.chromium.launch(headless=True)
        ctx = browser.new_context(viewport={''width'':1920,''height'':1080})
        pg = ctx.new_page()
        pg.goto(BASE_URL, wait_until=''domcontentloaded'')
        yield pg
        browser.close()

def test_check_faq_link_visibility(page):
    expect(page.locator(''a[href*=''faq'']'').first).to_be_visible(timeout=15000)

def test_click_faq_link(page):
    page.locator(''a[href*=''faq'']'').first.click()
    page.wait_for_load_state(''domcontentloaded'')
    expect(page).to_have_url(re.compile(r''faq''))

