const BASE_URL = ''https://rescat.tn/'';

describe(''NexTest Full Coverage Suite'', () => {
  beforeEach(() => { cy.visit(BASE_URL); });

  // [HEADER]
  it(''Check FAQ link visibility'', () => {
    cy.get(''a[href*=''faq'']'').first().should(''exist'');
  });

  // [HEADER]
  it(''Click FAQ link'', () => {
    cy.get(''a[href*=''faq'']'').first().click();
    cy.url().should(''include'', ''faq'');
  });

  // [HEADER]
  it(''Check Plan du Site link visibility'', () => {
    cy.get(''a[href*=''plan-du-site'']'').first().should(''exist'');
  });

  // [HEADER]
  it(''Click Plan du Site link'', () => {
    cy.get(''a[href*=''plan-du-site'']'').first().click();
    cy.url().should(''include'', ''plan-du-site'');
  });

  // [HEADER]
  it(''Check Glossaire link visibility'', () => {
    cy.get(''a[href*=''glossaire'']'').first().should(''exist'');
  });

  // [HEADER]
  it(''Click Glossaire link'', () => {
    cy.get(''a[href*=''glossaire'']'').first().click();
    cy.url().should(''include'', ''glossaire'');
  });

  // [HEADER]
  it(''Check FR link visibility'', () => {
    cy.get(''a[href*=''#pll_switcher'']'').first().should(''exist'');
  });

  // [HEADER]
  it(''Click FR link'', () => {
    cy.get(''a[hreflang=''fr'']'').first().click();
    cy.url().should(''include'', ''fr'');
  });

  // [HEADER]
  it(''Check AR link visibility'', () => {
    cy.get(''a[href*=''%d8%a7%d9%84%d8%a7%d8%b3%d8%aa%d9%82%d8%a8%d8%a7%d9%84'']'').first().should(''exist'');
  });

  // [HEADER]
  it(''Click AR link'', () => {
    cy.get(''a[hreflang=''ar'']'').first().click();
    cy.url().should(''include'', ''ar'');
  });

  // [HEADER]
  it(''Check EN link visibility'', () => {
    cy.get(''a[href*=''home'']'').first().should(''exist'');
  });

  // [HEADER]
  it(''Click EN link'', () => {
    cy.get(''a[hreflang=''en'']'').first().click();
    cy.url().should(''include'', ''en'');
  });

  // [HEADER]
  it(''Check logo visibility'', () => {
    cy.get(''img[src*=''final_logo_pirc_ar-1.png'']'').first().should(''exist'');
  });

  // [WORKFLOW]
  it(''Verify FAQ URL'', () => {
    cy.get(''N/A'').first().should(''exist'');
  });

  // [WORKFLOW]
  it(''Return to homepage'', () => {
    cy.get(''a[href=''/'']'').first().click();
    cy.get(''a[href=''/'']'').should(''be.visible'');
  });

