        browser = p.chromium.launch(headless=True)
        ctx = browser.new_context(viewport={''width'':1920,''height'':1080})
        pg = ctx.new_page()
        pg.goto(BASE_URL, wait_until=''domcontentloaded'')
        yield pg
        browser.close()

