def test_nav_link__faq(page):
    try: expect(page.locator(''a[href*=''faq'']'').first).to_be_visible(timeout=10000)
    except Exception: pytest.skip(''Optional: a[href*=''faq'']'')

def test_image__scraper_icon_png(page):
