ation URL","category":"functional","priority":"high","section":"workflow","assertion":{"type":"url_contains","value":"www.scrapethissite.com","selector_target":""},"base_url":"https:\/\/www.scrapethissite.com\/pages\/forms\/","description":"Verify destination URL","optional":false},{"id":20,"name":"Return to homepage","action":"click","selector":"a[href=''\/'']","value":"","expected":"Return to homepage","category":"functional","priority":"high","section":"workflow","assertion":{"type":"url_contains","value":"\/","selector_target":""},"base_url":"https:\/\/www.scrapethissite.com\/pages\/forms\/","description":"Return to homepage","optional":false}]', 'from playwright.sync_api import sync_playwright, expect
import pytest, re

BASE_URL = ''https://www.scrapethissite.com/pages/forms/''

@pytest.fixture(scope=''module'')
def page():
    with sync_playwright() as p:
        browser = p.chromium.launch(headless=True)
        ctx = browser.new_context(viewport={''width'':1920,''height'':1080})
        pg = ctx.new_page()
        pg.goto(BASE_URL, wait_until=''domcontentloaded'')
        yield pg
        browser.close()

def test_check_scrape_this_site_link_visibility(page):
    expect(page.locator(''a[href*=''www.scrapethissite.com'']'').first).to_be_visible(timeout=15000)

def test_click_scrape_this_site_link(page):
    page.locator(''a[href*=''www.scrapethissite.com'']'').first.click()
    page.wait_for_load_state(''domcontentloaded'')
    expect(page).to_have_url(re.compile(r''www\.scrapethissite\.com''))

def test_check_sandbox_link_visibility(page):
    expect(page.locator(''a[href*=''pages'']'').first).to_be_visible(timeout=15000)

def test_click_sandbox_link(page):
    page.locator(''a[href*=''pages'']'').first.click()
    page.wait_for_load_state(''domcontentloaded'')
    expect(page).to_have_url(re.compile(r''pages''))

def test_check_lessons_link_visibility(page):
    expect(page.locator(''a[href*=''lessons'']'').first).to_be_visible(timeout=15000)

def test_click_lessons_link(page):
    page.locator(''a[href*=''lessons'']'').first.click()
    page.wait_for_load_state(''domcontentloaded'')
    expect(page).to_have_url(re.compile(r''lessons''))

def test_check_faq_link_visibility(page):
    expect(page.locator(''a[href*=''faq'']'').first).to_be_visible(timeout=15000)

def test_click_faq_link(page):
    page.locator(''a[href*=''faq'']'').first.click()
    page.wait_for_load_state(''domcontentloaded'')
    expect(page).to_have_url(re.compile(r''faq''))

def test_check_login_link_visibility(page):
    expect(page.locator(''a[href*=''login'']'').first).to_be_visible(timeout=15000)

def test_click_login_link(page):
    page.locator(''a[href*=''login'']'').first.click()
    page.wait_for_load_state(''domcontentloaded'')
    expect(page).to_have_url(re.compile(r''login''))

def test_check_search_input_field_is_visible(page):
    expect(page.locator(''#q'').first).to_be_visible(timeout=15000)

def test_fill_search_input_field_with_test_data(page):
    page.fill(''#q'',''Test Team'')
    expect(page.locator(''#q'')).to_have_value(''Test Team'')

def test_check_per_page_input_field_is_visible(page):
    expect(page.locator(''#per_page'').first).to_be_visible(timeout=15000)

def test_fill_per_page_input_field_with_test_data(page):
    page.fill(''#per_page'',''10'')
    expect(page.locator(''#per_page'')).to_have_value(''10'')

def test_check_form_is_visible(page):
    expect(page.locator(''form'').first).to_be_visible(timeout=15000)

def test_submit_form_with_valid_data(page):
    page.locator(''form'').first.click()
    page.wait_for_load_state(''domcontentloaded'')
    expect(page.locator(''.success'').first).to_be_visible(timeout=15000)

def test_check_search_button_visibility(page):
    expect(page.locator(''input[type=''submit'']'').first).to_be_visible(timeout=15000)

def test_click_search_button(page):
    page.locator(''input[type=''submit'']'').first.click()
    page.wait_for_load_state(''domcontentloaded'')
    expect(page).to_have_url(re.compile(r''https://www\.scrapethissite\.com/pages/forms/''))

def test_verify_destination_url(page):
    expect(page.locator('''').first).to_be_visible(timeout=15000)

def test_return_to_homepage(page):
    page.locator(''a[href=''/'']'').first.click()
    page.wait_for_load_state(''domcontentloaded'')
    expect(page).to_have_url(re.compile(r''/''))
