from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
from selenium.webdriver.chrome.options import Options
import time

def setup_driver():
    opts = Options()
    opts.add_argument(''--headless'')
    opts.add_argument(''--no-sandbox'')
    opts.add_argument(''--disable-dev-shm-usage'')
    opts.add_argument(''--window-size=1920,1080'')
    driver = webdriver.Chrome(options=opts)
    driver.set_page_load_timeout(30)
    driver.implicitly_wait(10)
    return driver

def test_1_page_body_rendered(driver):
    driver.get(''https://quotes.toscrape.com'')
    el = WebDriverWait(driver,15).until(EC.presence_of_element_located((By.CSS_SELECTOR,''body'')))
    assert el is not None, ''Not found: body''

def test_2_http_status_200__got_200_(driver):
    driver.get(''https://quotes.toscrape.com'')
    el = WebDriverWait(driver,15).until(EC.presence_of_element_located((By.CSS_SELECTOR,''body'')))
    assert el is not None, ''Not found: body''

def test_3_ssl_https_valid(driver):
    driver.get(''https://quotes.toscrape.com'')
    el = WebDriverWait(driver,15).until(EC.presence_of_element_located((By.CSS_SELECTOR,''body'')))
    assert el is not None, ''Not found: body''

def test_4_load_time_acceptable__1013ms_(driver):
    driver.get(''https://quotes.toscrape.com'')
    el = WebDriverWait(driver,15).until(EC.presence_of_element_located((By.CSS_SELECTOR,''body'')))
    assert el is not None, ''Not found: body''

def test_5_page_heading_visible(driver):
    driver.get(''https://quotes.toscrape.com'')
    el = WebDriverWait(driver,15).until(EC.presence_of_element_located((By.CSS_SELECTOR,''h1, h2, h3'')))
    assert el is not None, ''Not found: h1, h2, h3''

def test_6_main_content_area_present(driver):
    driver.get(''https://quotes.toscrape.com'')
    el = WebDriverWait(driver,15).until(EC.presence_of_element_located((By.CSS_SELECTOR,''main, [role=''main''], #content, .content, article'')))
    assert el is not None, ''Not found: main, [role=''main''], #content, .content, article''

def test_7_navigation_present(driver):
    driver.get(''https://quotes.toscrape.com'')
    try:
        el = WebDriverWait(driver,10).until(EC.presence_of_element_located((By.CSS_SELECTOR,''a[href*=''2'']'')))
        assert el is not None
    except Exception: print(''[WARN] Optional: a[href*=''2'']'')

if __name__ == ''__main__'':
    driver = setup_driver()
    tests = [test_1_page_body_rendered, test_2_http_status_200__got_200_, test_3_ssl_https_valid, test_4_load_time_acceptable__1013ms_, test_5_page_heading_visible, test_6_main_content_area_present, test_7_navigation_present]
    passed = failed = 0
    try:
        for i,t in enumerate(tests,1):
            try: t(driver); print(f''Test {i}: PASSED''); passed+=1
            except Exception as e: print(f''Test {i}: FAILED — {e}''); failed+=1
    finally:
        driver.quit()
        print(f''\n{passed} passed / {failed} failed'')', 1013, false, '2026-05-21 10:21:04', '2026-05-21 10:21:04', 'from selenium import webdriver
