import pytest, re

BASE_URL = ''https://books.toscrape.com/''

@pytest.fixture(scope=''module'')
def page():
    with sync_playwright() as p:
        browser = p.chromium.launch(headless=True)
        ctx = browser.new_context(viewport={''width'':1920,''height'':1080})
        pg = ctx.new_page()
        pg.goto(BASE_URL, wait_until=''domcontentloaded'')
        yield pg
        browser.close()

def test_page_body_rendered(page):
    expect(page.locator(''body'').first).to_be_visible(timeout=15000)

def test_http_status_200__got_200_(page):
    expect(page.locator(''body'').first).to_be_visible(timeout=15000)

def test_ssl_https_valid(page):
    expect(page.locator(''body'').first).to_be_visible(timeout=15000)

def test_load_time_acceptable__3397ms_(page):
    expect(page.locator(''body'').first).to_be_visible(timeout=15000)

def test_page_heading_visible(page):
    expect(page.locator(''h1, h2, h3'').first).to_be_visible(timeout=15000)

def test_main_content_area_present(page):
    expect(page.locator(''main, [role=''main''], #content, .content, article'').first).to_be_visible(timeout=15000)

def test_image__a_light_in_the_attic(page):
    try: expect(page.locator(''img[alt=''A Light in the Attic'']'').first).to_be_visible(timeout=10000)
    except Exception: pytest.skip(''Optional: img[alt=''A Light in the Attic'']'')

def test_image__tipping_the_velvet(page):
    try: expect(page.locator(''img[alt=''Tipping the Velvet'']'').first).to_be_visible(timeout=10000)
    except Exception: pytest.skip(''Optional: img[alt=''Tipping the Velvet'']'')

def test_image__soumission(page):
    try: expect(page.locator(''img[alt=''Soumission'']'').first).to_be_visible(timeout=10000)
    except Exception: pytest.skip(''Optional: img[alt=''Soumission'']'')

def test_image__sharp_objects(page):
    try: expect(page.locator(''img[alt=''Sharp Objects'']'').first).to_be_visible(timeout=10000)
    except Exception: pytest.skip(''Optional: img[alt=''Sharp Objects'']'')

def test_image__sapiens__a_brief_history_of_human(page):
    try: expect(page.locator(''img[alt=''Sapiens: A Brief History of Humankind'']'').first).to_be_visible(timeout=10000)
