import pytest

BASE_URL = ''https://anpe.demopro.tn:10443/reception''

@pytest.fixture(scope=''module'')
def page():
    with sync_playwright() as p:
        browser = p.chromium.launch(
            headless=True,
            args=[''--ignore-certificate-errors'', ''--no-sandbox'']
        )
        ctx = browser.new_context(
            viewport={''width'': 1440, ''height'': 900},
            ignore_https_errors=True,
        )
        pg = ctx.new_page()
        pg.goto(BASE_URL, wait_until=''domcontentloaded'', timeout=30000)
        yield pg
        browser.close()

def test_http_status_200__got_200_(page):
    expect(page.locator(''body'').first).to_be_visible(timeout=15000)

