"priority":"high","expected":"Nav link ''Lessons'' present","description":"Nav link ''Lessons'' present","section":"smoke","id":9,"base_url":"https:\/\/www.scrapethissite.com\/"},{"name":"Nav link: FAQ","selector":"a[href*=''faq'']","type":"nav_link","tier":1,"score":72,"optional":true,"reason":"Nav link ''FAQ'' present","action":"check_visible","value":"","assertion":null,"category":"smoke","priority":"high","expected":"Nav link ''FAQ'' present","description":"Nav link ''FAQ'' present","section":"smoke","id":10,"base_url":"https:\/\/www.scrapethissite.com\/"},{"name":"Image: scraper-icon.png","selector":"#townhall-logo","type":"image","tier":2,"score":45,"optional":true,"reason":"Image ''scraper-icon.png'' visible and loaded","action":"check_visible","value":"","assertion":null,"category":"smoke","priority":"medium","expected":"Image ''scraper-icon.png'' visible and loaded","description":"Image ''scraper-icon.png'' visible and loaded","section":"smoke","id":11,"base_url":"https:\/\/www.scrapethissite.com\/"}]', 'from playwright.sync_api import sync_playwright, expect
import pytest, re

BASE_URL = ''https://www.scrapethissite.com/''

@pytest.fixture(scope=''module'')
def page():
    with sync_playwright() as p:
        browser = p.chromium.launch(headless=True)
        ctx = browser.new_context(viewport={''width'':1920,''height'':1080})
        pg = ctx.new_page()
        pg.goto(BASE_URL, wait_until=''domcontentloaded'')
        yield pg
        browser.close()

def test_page_body_rendered(page):
    expect(page.locator(''body'').first).to_be_visible(timeout=15000)

def test_http_status_200__got_200_(page):
    expect(page.locator(''body'').first).to_be_visible(timeout=15000)

def test_ssl_https_valid(page):
    expect(page.locator(''body'').first).to_be_visible(timeout=15000)

def test_load_time_acceptable__5564ms_(page):
    expect(page.locator(''body'').first).to_be_visible(timeout=15000)

def test_auth_entry_point_present(page):
    expect(page.locator(''a[href*=''login'']'').first).to_be_visible(timeout=15000)

def test_page_heading_visible(page):
    expect(page.locator(''h1, h2, h3'').first).to_be_visible(timeout=15000)

def test_main_content_area_present(page):
    expect(page.locator(''main, [role=''main''], #content, .content, article'').first).to_be_visible(timeout=15000)

def test_nav_link__sandbox(page):
    try: expect(page.locator(''a[href*=''pages'']'').first).to_be_visible(timeout=10000)
    except Exception: pytest.skip(''Optional: a[href*=''pages'']'')

def test_nav_link__lessons(page):
    try: expect(page.locator(''a[href*=''lessons'']'').first).to_be_visible(timeout=10000)
    except Exception: pytest.skip(''Optional: a[href*=''lessons'']'')

def test_nav_link__faq(page):
    try: expect(page.locator(''a[href*=''faq'']'').first).to_be_visible(timeout=10000)
    except Exception: pytest.skip(''Optional: a[href*=''faq'']'')

def test_image__scraper_icon_png(page):
