"action":"check_visible","selector":"a.btn","value":"","expected":"CTA button is visible","category":"functional","priority":"high","section":"hero","assertion":{"type":"element_visible","value":null,"selector_target":"a.btn"},"base_url":"https:\/\/www.scrapethissite.com\/","description":"CTA button is visible","optional":false},{"id":11,"name":"Click CTA button","action":"click","selector":"a.btn","value":"","expected":"Redirect to new page","category":"functional","priority":"high","section":"hero","assertion":{"type":"url_contains","value":"\/pages\/","selector_target":null},"base_url":"https:\/\/www.scrapethissite.com\/","description":"Redirect to new page","optional":false},{"id":12,"name":"Verify Sandbox URL","action":"check_visible","selector":"","value":"","expected":"Sandbox URL verified","category":"functional","priority":"high","section":"workflow","assertion":{"type":"url_contains","value":"pages","selector_target":""},"base_url":"https:\/\/www.scrapethissite.com\/","description":"Sandbox URL verified","optional":false},{"id":13,"name":"Return to homepage","action":"click","selector":"a[href=''\/'']","value":"","expected":"Homepage loaded","category":"functional","priority":"high","section":"workflow","assertion":{"type":"url_contains","value":"\/","selector_target":""},"base_url":"https:\/\/www.scrapethissite.com\/","description":"Homepage loaded","optional":false}]', 'from playwright.sync_api import sync_playwright, expect
import pytest, re

BASE_URL = ''https://www.scrapethissite.com/''

@pytest.fixture(scope=''module'')
def page():
    with sync_playwright() as p:
        browser = p.chromium.launch(headless=True)
        ctx = browser.new_context(viewport={''width'':1920,''height'':1080})
        pg = ctx.new_page()
        pg.goto(BASE_URL, wait_until=''domcontentloaded'')
        yield pg
        browser.close()

def test_check_visibility_of_sandbox_nav_link(page):
    expect(page.locator(''a[href*=''pages'']'').first).to_be_visible(timeout=15000)

def test_click_on_sandbox_nav_link(page):
    page.locator(''a[href*=''pages'']'').first.click()
    page.wait_for_load_state(''domcontentloaded'')
    expect(page).to_have_url(re.compile(r''pages''))

def test_check_visibility_of_lessons_nav_link(page):
    expect(page.locator(''a[href*=''lessons'']'').first).to_be_visible(timeout=15000)

def test_click_on_lessons_nav_link(page):
    page.locator(''a[href*=''lessons'']'').first.click()
    page.wait_for_load_state(''domcontentloaded'')
    expect(page).to_have_url(re.compile(r''lessons''))

def test_check_visibility_of_faq_nav_link(page):
    expect(page.locator(''a[href*=''faq'']'').first).to_be_visible(timeout=15000)

def test_click_on_faq_nav_link(page):
    page.locator(''a[href*=''faq'']'').first.click()
    page.wait_for_load_state(''domcontentloaded'')
    expect(page).to_have_url(re.compile(r''faq''))

def test_check_visibility_of_login_nav_link(page):
    expect(page.locator(''a[href*=''login'']'').first).to_be_visible(timeout=15000)

def test_click_on_login_nav_link(page):
    page.locator(''a[href*=''login'']'').first.click()
    page.wait_for_load_state(''domcontentloaded'')
    expect(page).to_have_url(re.compile(r''login''))

def test_check_hero_section_visibility(page):
    expect(page.locator(''.hero'').first).to_be_visible(timeout=15000)

def test_check_cta_button_visibility(page):
    expect(page.locator(''a.btn'').first).to_be_visible(timeout=15000)

def test_click_cta_button(page):
    page.locator(''a.btn'').first.click()
    page.wait_for_load_state(''domcontentloaded'')
    expect(page).to_have_url(re.compile(r''/pages/''))

def test_verify_sandbox_url(page):
    expect(page.locator('''').first).to_be_visible(timeout=15000)

def test_return_to_homepage(page):
    page.locator(''a[href=''/'']'').first.click()
    page.wait_for_load_state(''domcontentloaded'')
    expect(page).to_have_url(re.compile(r''/''))
