INSERT INTO public.test_jobs (id, project_id, type, status, payload, result, error, completed_at, created_at, updated_at) VALUES (4, 27, 'security', 'completed', '{"url":"https:\/\/anpe.demopro.tn:10443\/dashboard","anpe_token":"","categories":null,"doc_text":"--- anpe_doc.txt ---\nANPE - Agence Nationale de Protection de l''Environnement\r\nApplication: Back-office web (Tunisia)\r\nBase URL: https:\/\/anpe.demopro.tn:10443\r\n\r\n== PAGES DISPONIBLES ==\r\n- \/admin-anpe\/login \u2192 Page de connexion\r\n- \/dashboard \u2192 Tableau de bord\r\n- \/reception \u2192 R\u00e9ception des dossiers\r\n- \/outbox \u2192 Dossiers sortants\r\n- \/statistiques \u2192 Graphiques\r\n- \/reunions \u2192 Gestion des r\u00e9unions\r\n- \/visites \u2192 Gestion des visites\r\n- \/traitement_dossier_eie \u2192 Traitement dossier EIE\r\n- \/traitement_dossier_ed \u2192 Traitement dossier ED\r\n- \/traitement_dossier_avis \u2192 Traitement dossier Avis\r\n- \/traitement_dossier_transaction \u2192 Traitement dossier Transaction\r\n- \/gestion_commission \u2192 Gestion des commissions\r\n- \/traitement_dossier_cc \u2192 Traitement dossier CC\r\n- \/traitement_dossier_af \u2192 Traitement dossier AF\r\n\r\n\r\n== API ENDPOINTS ==\r\nBase API URL: https:\/\/anpe.back.demopro.tn:10443\r\n\r\nAUTH:\r\nPOST \/api\/v1\/auth\/login \u2192 Login (requires captcha, returns 422)\r\nGET \/api\/v1\/auth\/me \u2192 Get current user info\r\n\r\nDASHBOARD:\r\nGET \/api\/v1\/admin\/dashboard\/stats \u2192 Dashboard statistics\r\nGET \/api\/v1\/admin\/dashboard\/dossiers \u2192 List dossiers\r\n\r\nDOSSIERS:\r\nGET \/api\/v1\/dossiers \u2192 List all dossiers\r\nGET \/api\/v1\/dossiers\/{id} \u2192 Get dossier detail\r\nPOST \/api\/v1\/dossiers \u2192 Create dossier\r\nPUT \/api\/v1\/dossiers\/{id} \u2192 Update dossier\r\nDELETE \/api\/v1\/dossiers\/{id} \u2192 Delete dossier\r\n\r\nUSERS:\r\nGET \/api\/v1\/users \u2192 List users\r\nPOST \/api\/v1\/users \u2192 Create user\r\n\r\nCOMMISSIONS:\r\nGET \/api\/v1\/commissions \u2192 List commissions\r\nPOST \/api\/v1\/commissions \u2192 Create commission\r\n\r\n== ROLES UTILISATEURS ==\r\n- Admin \u2192 acc\u00e8s complet\r\n- Agent \u2192 acc\u00e8s limit\u00e9 (reception, outbox)\r\n\r\n== FONCTIONNALITES PRINCIPALES ==\r\n- Traitement des dossiers EIE, ED, Avis, Transaction\r\n- Gestion des commissions et r\u00e9unions\r\n- Tableau de bord avec KPIs\r\n- Export de rapports\r\n\r\n== TECHNOLOGIES ==\r\n- Frontend: React\r\n- Backend: Laravel API\r\n- Auth: JWT token","user_id":10}', '{"generation":{"user_id":10,"project_id":27,"url":"https:\/\/anpe.demopro.tn:10443\/dashboard","framework":"Pytest","test_type":"security","status":"completed","test_cases":[{"id":1,"name":"Access dashboard without token","category":"auth","severity":"critical","test_type":"no_token","url":"https:\/\/anpe.demopro.tn:10443\/dashboard","status":"pass","reason":"\u2713 Redirected to login page \u2014 protected route secure \u2713","duration":"11373ms","description":"Dashboard must redirect unauthenticated users to login","expect":"redirect_to_login"},{"id":2,"name":"Access reception without token","category":"auth","severity":"critical","test_type":"no_token","url":"https:\/\/anpe.demopro.tn:10443\/reception","status":"pass","reason":"\u2713 Redirected to login page \u2014 protected route secure \u2713","duration":"11315ms","description":"Reception page must redirect unauthenticated users","expect":"redirect_to_login"},{"id":3,"name":"XSS in search field","category":"xss","severity":"high","test_type":"xss_input","url":"https:\/\/anpe.demopro.tn:10443\/reception","status":"warn","reason":"Input field not found on page \u2014 test inconclusive","duration":"16471ms","description":"Search field must sanitize XSS input","expect":"xss_not_executed"},{"id":4,"name":"Session token exposure check","category":"session","severity":"medium","test_type":"dom_inspect","url":"https:\/\/anpe.demopro.tn:10443\/dashboard","status":"pass","reason":"\u271